# ---------------------------------------------------------------------------
# SAFE SOURCE DISCOVERY
# ---------------------------------------------------------------------------

IGNORED_DIRECTORIES = {
    ".git",
    ".hg",
    ".svn",
    "__pycache__",
    ".pytest_cache",
    ".mypy_cache",
    ".ruff_cache",
    ".venv",
    "venv",
    "env",
    "node_modules",
    "dist",
    "build",
}


def discover_python_files(root: Path) -> list[Path]:
    files: list[Path] = []

    for path in root.rglob("*.py"):
        if any(part in IGNORED_DIRECTORIES for part in path.parts):
            continue

        if path.is_file():
            files.append(path)

    return sorted(files)


# ---------------------------------------------------------------------------
# AST HELPERS
# ---------------------------------------------------------------------------

def qualified_name(node: ast.AST) -> str:
    if isinstance(node, ast.Name):
        return node.id

    if isinstance(node, ast.Attribute):
        parent = qualified_name(node.value)
        return f"{parent}.{node.attr}" if parent else node.attr

    return ast.unparse(node) if hasattr(ast, "unparse") else "<expression>"


def decorator_name(node: ast.expr) -> str:
    return qualified_name(node)


def extract_docstring(node: ast.AST) -> str | None:
    return ast.get_docstring(node)


def source_fingerprint(node: ast.AST) -> str:
    """
    Normalize an AST subtree before hashing.

    Names and literal values are retained because Phase 1 must not
    incorrectly classify every structurally similar function as a duplicate.
    """

    try:
        normalized = ast.dump(
            node,
            annotate_fields=True,
            include_attributes=False,
        )
    except Exception:
        normalized = repr(node)

    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


# ---------------------------------------------------------------------------
# FILE ANALYSIS
# ---------------------------------------------------------------------------

class SourceAnalyzer(ast.NodeVisitor):
    def __init__(self, file_path: Path, root: Path) -> None:
        self.file_path = file_path
        self.root = root

        self.components: list[ComponentRecord] = []
        self.functions: list[FunctionRecord] = []
        self.dependencies: list[DependencyRecord] = []
        self.tests: list[TestRecord] = []

        self.current_function: str | None = None

    @property
    def relative_file(self) -> str:
        return str(self.file_path.relative_to(self.root))

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            self.dependencies.append(
                DependencyRecord(
                    source_file=self.relative_file,
                    dependency=alias.name,
                    kind="import",
                    line=node.lineno,
                )
            )

        self.generic_visit(node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        module = node.module or ""

        self.dependencies.append(
            DependencyRecord(
                source_file=self.relative_file,
                dependency=module,
                kind="from_import",
                line=node.lineno,
            )
        )

        self.generic_visit(node)

    def visit_ClassDef(self, node: ast.ClassDef) -> None:
        bases = tuple(qualified_name(base) for base in node.bases)

        methods = tuple(
            child.name
            for child in node.body
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef))
        )

        decorators = tuple(
            decorator_name(dec)
            for dec in node.decorator_list
        )

        self.components.append(
            ComponentRecord(
                name=node.name,
                kind="class",
                file=self.relative_file,
                line=node.lineno,
                bases=bases,
                methods=methods,
                decorators=decorators,
                docstring=extract_docstring(node),
            )
        )

        if node.name.lower().startswith("test"):
            self.tests.append(
                TestRecord(
                    file=self.relative_file,
                    line=node.lineno,
                    name=node.name,
                    kind="test_class",
                )
            )

        self.generic_visit(node)

    def _visit_function(
        self,
        node: ast.FunctionDef | ast.AsyncFunctionDef,
    ) -> None:
        decorators = tuple(
            decorator_name(dec)
            for dec in node.decorator_list
        )

        calls: list[str] = []

        for child in ast.walk(node):
            if isinstance(child, ast.Call):
                calls.append(qualified_name(child.func))

        record = FunctionRecord(
            name=node.name,
            file=self.relative_file,
            line=node.lineno,
            is_async=isinstance(node, ast.AsyncFunctionDef),
            decorators=decorators,
            calls=tuple(sorted(set(calls))),
            docstring=extract_docstring(node),
        )

        self.functions.append(record)

        lower_name = node.name.lower()

        if (
            lower_name.startswith("test")
            or "pytest" in decorators
            or "unittest" in decorators
        ):
            self.tests.append(
                TestRecord(
                    file=self.relative_file,
                    line=node.lineno,
                    name=node.name,
                    kind="test_function",
                )
            )

        previous = self.current_function
        self.current_function = node.name

        self.generic_visit(node)

        self.current_function = previous

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        self._visit_function(node)

    def visit_AsyncFunctionDef(
        self,
        node: ast.AsyncFunctionDef,
    ) -> None:
        self._visit_function(node)


