def normalized(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", value.lower())


def collect_source_terms(
    components: Iterable[ComponentRecord],
    functions: Iterable[FunctionRecord],
) -> set[str]:
    terms: set[str] = set()

    for component in components:
        terms.add(normalized(component.name))

        for method in component.methods:
            terms.add(normalized(method))

    for function in functions:
        terms.add(normalized(function.name))

        for call in function.calls:
            terms.add(normalized(call))

    return terms


def assess_capabilities(
    components: list[ComponentRecord],
    functions: list[FunctionRecord],
) -> list[CapabilityAssessment]:
    terms = collect_source_terms(components, functions)
    assessments: list[CapabilityAssessment] = []

    for capability in CAPABILITY_SCOPE:
        evidence_terms = CAPABILITY_TERMS.get(capability, ())

        matches = [
            term
            for term in evidence_terms
            if normalized(term) in terms
        ]

        if not matches:
            assessments.append(
                CapabilityAssessment(
                    capability=capability,
                    status="UNKNOWN",
                    confidence="LOW",
                )
            )
            continue

        # Presence of names is NOT proof of implementation.
        assessments.append(
            CapabilityAssessment(
                capability=capability,
                evidence=matches,
                status="UNKNOWN",
                confidence="LOW",
            )
        )

    return assessments


# ---------------------------------------------------------------------------
# DUPLICATION ANALYSIS
# ---------------------------------------------------------------------------

def detect_structural_duplicates(
    root: Path,
    files: list[Path],
) -> list[DuplicationRecord]:
    buckets: dict[str, list[str]] = {}

    for file_path in files:
        try:
            tree = ast.parse(
                file_path.read_text(encoding="utf-8"),
                filename=str(file_path),
            )
        except Exception:
            continue

        for node in ast.walk(tree):
            if not isinstance(
                node,
                (
                    ast.ClassDef,
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                ),
            ):
                continue

            fingerprint = source_fingerprint(node)

            location = (
                f"{file_path.relative_to(root)}:"
                f"{getattr(node, 'lineno', '?')}:"
                f"{getattr(node, 'name', '<anonymous>')}"
            )

            buckets.setdefault(fingerprint, []).append(location)

    results: list[DuplicationRecord] = []

    for fingerprint, occurrences in buckets.items():
        if len(occurrences) > 1:
            results.append(
                DuplicationRecord(
                    fingerprint=fingerprint,
                    occurrences=tuple(sorted(occurrences)),
                    kind="structural_ast_duplicate",
                )
            )

    return results


# ---------------------------------------------------------------------------
# ARCHITECTURAL / SECURITY SIGNALS
# ---------------------------------------------------------------------------

def derive_architectural_signals(
    report: AuditReport,
) -> None:
    component_names = {
        normalized(component.name)
        for component in report.components
    }

    function_names = {
        normalized(function.name)
        for function in report.functions
    }

    all_names = component_names | function_names

    # Phase 1 only records gaps. It does not implement them.
    expected_signals = {
        "state": {
            "security_state_control",
            "securitystate",
            "statesnapshot",
        },
        "verification": {
            "verification",
            "verifier",
            "independentverification",
        },
        "authorization": {
            "authorization",
            "authorize",
            "authority",
        },
        "audit": {
            "audit",
            "auditrecord",
            "auditlog",
        },
        "recovery": {
            "recovery",
            "regeneration",
            "reconstruct",
        },
    }

    for area, candidates in expected_signals.items():
        if not any(
            normalized(candidate) in all_names
            for candidate in candidates
        ):
            report.architectural_gaps.append(
                f"No direct structural evidence found for {area}."
            )

    # Data-flow indicators.
    dependency_names = {
        normalized(dep.dependency)
        for dep in report.dependencies
    }

    if any(
        term in dependency_names
        for term in ("requests", "httpx", "aiohttp", "urllib")
    ):
        report.data_flow_indicators.append(
            "External/network data ingestion dependency detected."
        )

    if any(
        "database" in normalized(dep.dependency)
        or "sql" in normalized(dep.dependency)
        for dep in report.dependencies
    ):
        report.data_flow_indicators.append(
            "Database/storage dependency detected."
        )

    # Trust-boundary indicators.
    if any(
        term in all_names
        for term in (
            "authenticate",
            "authentication",
            "authorize",
            "authorization",
            "permission",
            "policy",
            "credential",
            "secret",
        )
    ):
        report.trust_boundary_indicators.append(
            "Identity/authorization/security-control terminology detected."
        )

    # Security findings.
    for duplicate in report.duplication:
        report.security_findings.append(
            "Structural duplication requires manual review: "
            + "; ".join(duplicate.occurrences)
        )


# ---------------------------------------------------------------------------
# STATIC SOURCE QUALITY CHECKS
# ---------------------------------------------------------------------------

def inspect_source_quality(
    report: AuditReport,
    files: list[Path],
) -> None:
    placeholder_patterns = (
        r"\bTODO\b",
        r"\bFIXME\b",
        r"\bpass\s*(?:#.*)?$",
        r"\bNotImplementedError\b",
        r"\bplaceholder\b",
        r"\bstub\b",
        r"\bmock\b",
    )

    for file_path in files:
        try:
            text = file_path.read_text(encoding="utf-8")
        except Exception as exc:
            report.errors.append(
                f"Could not read {file_path}: {exc}"
            )
            continue

        for line_number, line in enumerate(text.splitlines(), 1):
            for pattern in placeholder_patterns:
                if re.search(pattern, line, re.IGNORECASE):
                    report.security_findings.append(
                        f"Potential placeholder/stub at "
                        f"{file_path.relative_to(report.project_root)}:"
                        f"{line_number}"
                    )
                    break


# ---------------------------------------------------------------------------
# MAIN AUDIT
# ---------------------------------------------------------------------------

def audit_project(project_root: str | Path) -> AuditReport:
    root = Path(project_root).resolve()

    if not root.exists():
        raise FileNotFoundError(
            f"Project root does not exist: {root}"
        )

    if not root.is_dir():
        raise NotADirectoryError(
            f"Project root is not a directory: {root}"
        )

    report = AuditReport(project_root=str(root))

    files = discover_python_files(root)
    report.files_scanned = len(files)
    report.python_files = len(files)

    for file_path in files:
        try:
            source = file_path.read_text(encoding="utf-8")

            try:
                tree = ast.parse(
                    source,
                    filename=str(file_path),
                    type_comments=True,
                )
            except SyntaxError as exc:
                report.errors.append(
                    f"Syntax error in "
                    f"{file_path.relative_to(root)}:"
                    f"{exc.lineno}:{exc.offset}: {exc.msg}"
                )
                continue

            analyzer = SourceAnalyzer(file_path, root)
            analyzer.visit(tree)

            report.components.extend(analyzer.components)
            report.functions.extend(analyzer.functions)
            report.dependencies.extend(analyzer.dependencies)
            report.tests.extend(analyzer.tests)

        except Exception as exc:
            report.errors.append(
                f"Analysis failure in "
                f"{file_path.relative_to(root)}: {exc}"
            )

    report.duplication = detect_structural_duplicates(
        root,
        files,
    )

    report.capabilities = assess_capabilities(
        report.components,
        report.functions,
    )

    derive_architectural_signals(report)
    inspect_source_quality(report, files)

    return report


# ---------------------------------------------------------------------------
# REPORT SERIALIZATION
# ---------------------------------------------------------------------------

def report_to_dict(report: AuditReport) -> dict[str, Any]:
    return asdict(report)


def write_report(
    report: AuditReport,
    output_path: str | Path,
) -> None:
    output = Path(output_path)

    output.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    output.write_text(
        json.dumps(
            report_to_dict(report),
            indent=2,
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )


def print_summary(report: AuditReport) -> None:
    print("=" * 72)
    print("HYDRA PHASE 1 — FORENSIC AUDIT")
    print("=" * 72)

    print(f"Project root : {report.project_root}")
    print(f"Python files : {report.python_files}")
    print(f"Components   : {len(report.components)}")
    print(f"Functions    : {len(report.functions)}")
    print(f"Dependencies : {len(report.dependencies)}")
    print(f"Tests        : {len(report.tests)}")
    print(f"Duplicates   : {len(report.duplication)}")
    print(f"Errors       : {len(report.errors)}")

    print("\nCAPABILITY EVIDENCE")
    print("-" * 72)

    for assessment in report.capabilities:
        evidence = ", ".join(assessment.evidence) or "none"

        print(
            f"{assessment.capability:42} "
            f"{assessment.status:32} "
            f"[{evidence}]"
        )

    print("\nARCHITECTURAL GAPS")
    print("-" * 72)

    if report.architectural_gaps:
        for gap in report.architectural_gaps:
            print(f"- {gap}")
    else:
        print("- None detected structurally.")

    print("\nTRUST BOUNDARY INDICATORS")
    print("-" * 72)

    for item in report.trust_boundary_indicators:
        print(f"- {item}")

    print("\nDATA FLOW INDICATORS")
    print("-" * 72)

    for item in report.data_flow_indicators:
        print(f"- {item}")

    print("\nERRORS")
    print("-" * 72)

    for error in report.errors:
        print(f"- {error}")

    print("=" * 72)


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main(argv: list[str] | None = None) -> int:
    args = argv if argv is not None else sys.argv[1:]

    if not args:
        print(
            "Usage:\n"
            "  python hydra_phase1_audit.py <new_hydra_project_root> "
            "[output.json]"
        )
        return 2

    project_root = args[0]
    output_path = (
        args[1]
        if len(args) > 1
        else "hydra_phase1_audit_report.json"
    )

    try:
        report = audit_project(project_root)
        print_summary(report)
        write_report(report, output_path)

        print(f"\nAudit report written to: {output_path}")

        # An audit can execute successfully even when the audited
        # technology itself is incomplete. Therefore this return code
        # represents audit execution, not technology readiness.
        return 0

    except Exception as exc:
        print(f"PHASE 1 AUDIT ERROR: {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
