def run_phase6_tests() -> unittest.result.TestResult:
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(
        TestTemporalSecurityGraph
    )

    runner = unittest.TextTestRunner(
        verbosity=2
    )

    return runner.run(suite)


if __name__ == "__main__":
    run_phase6_tests()
