class Phase14Tests(unittest.TestCase):

    def setUp(self):

        self.engine = (
            IndependentVerificationEngine()
        )

        self.engine.add_expected(
            ExpectedOutcome(
                outcome_id="expected-1",
                scope_id="tenant-a",
                key="security_state",
                expected_value="protected",
            )
        )

    # ========================================================================
    # Registration
    # ========================================================================

    def test_expected_registration(self):

        result = self.engine.get_expected(
            "expected-1"
        )

        self.assertEqual(
            result.expected_value,
            "protected",
        )

    def test_duplicate_expected_rejected(self):

        with self.assertRaises(ValueError):
            self.engine.add_expected(
                ExpectedOutcome(
                    outcome_id="expected-1",
                    scope_id="tenant-a",
                    key="x",
                    expected_value=True,
                )
            )

    # ========================================================================
    # Successful verification
    # ========================================================================

    def test_success(self):

        observation = ObservedOutcome(
            observation_id="obs-1",
            scope_id="tenant-a",
            key="security_state",
            observed_value="protected",
            observed_at=utc_now(),
            source_id="independent-monitor",
            confidence=0.95,
        )

        evidence = IndependentEvidence(
            evidence_id="evidence-1",
            scope_id="tenant-a",
            evidence_type=EvidenceType.INDEPENDENT_SENSOR,
            source_id="sensor-a",
            key="security_state",
            value="protected",
            collected_at=utc_now(),
            integrity=EvidenceIntegrity.VALID,
            confidence=0.90,
        )

        self.engine.add_evidence(
            evidence
        )

        result = self.engine.verify(
            scope_id="tenant-a",
            subject_reference="action-1",
            expected_outcome_ids=(
                "expected-1",
            ),
            observed_outcomes=(
                observation,
            ),
            evidence_ids=(
                "evidence-1",
            ),
        )

        self.assertEqual(
            result.status,
            VerificationStatus.SUCCESS,
        )

        self.assertGreater(
            result.confidence,
            0.5,
        )

    # ========================================================================
    # Failed verification
    # ========================================================================

    def test_failed_verification(self):

        observation = ObservedOutcome(
            observation_id="obs-failed",
            scope_id="tenant-a",
            key="security_state",
            observed_value="compromised",
            observed_at=utc_now(),
            source_id="sensor",
        )

        result = self.engine.verify(
            scope_id="tenant-a",
            subject_reference="action-failed",
            expected_outcome_ids=(
                "expected-1",
            ),
            observed_outcomes=(
                observation,
            ),
            evidence_ids=(),
        )

        self.assertEqual(
            result.status,
            VerificationStatus.FAILED,
        )

    # ========================================================================
    # Partial verification
    # ========================================================================

    def test_partial_verification(self):

        self.engine.add_expected(
            ExpectedOutcome(
                outcome_id="expected-2",
                scope_id="tenant-a",
                key="network_state",
                expected_value="segmented",
            )
        )

        observations = (
            ObservedOutcome(
                observation_id="obs-a",
                scope_id="tenant-a",
                key="security_state",
                observed_value="protected",
                observed_at=utc_now(),
                source_id="sensor-a",
            ),
            ObservedOutcome(
                observation_id="obs-b",
                scope_id="tenant-a",
                key="network_state",
                observed_value="flat",
                observed_at=utc_now(),
                source_id="sensor-b",
            ),
        )

        result = self.engine.verify(
            scope_id="tenant-a",
            subject_reference="action-partial",
            expected_outcome_ids=(
                "expected-1",
                "expected-2",
            ),
            observed_outcomes=observations,
            evidence_ids=(),
        )

        self.assertEqual(
            result.status,
            VerificationStatus.PARTIAL,
        )

    # ========================================================================
    # Unknown
    # ========================================================================

    def test_unknown_without_observation(self):

        result = self.engine.verify(
            scope_id="tenant-a",
            subject_reference="action-unknown",
            expected_outcome_ids=(
                "expected-1",
            ),
            observed_outcomes=(),
            evidence_ids=(),
        )

        self.assertEqual(
            result.status,
            VerificationStatus.FAILED,
        )

        self.assertEqual(
            result.comparisons[0].reason,
            "no observation available",
        )

    # ========================================================================
    # Evidence contradiction
    # ========================================================================

    def test_evidence_contradiction(self):

        evidence = IndependentEvidence(
            evidence_id="contradictory",
            scope_id="tenant-a",
            evidence_type=EvidenceType.INDEPENDENT_SENSOR,
            source_id="independent-sensor",
            key="security_state",
            value="compromised",
            collected_at=utc_now(),
            integrity=EvidenceIntegrity.VALID,
            confidence=0.95,
        )

        self.engine.add_evidence(
            evidence
        )

        observation = ObservedOutcome(
            observation_id="obs-conflict",
            scope_id="tenant-a",
            key="security_state",
            observed_value="protected",
            observed_at=utc_now(),
            source_id="primary-system",
        )

        result = self.engine.verify(
            scope_id="tenant-a",
            subject_reference="conflicting-action",
            expected_outcome_ids=(
                "expected-1",
            ),
            observed_outcomes=(
                observation,
            ),
            evidence_ids=(
                "contradictory",
            ),
        )

        self.assertEqual(
            result.status,
            VerificationStatus.FAILED,
        )

    # ========================================================================
    # Scope isolation
    # ========================================================================

    def test_scope_mismatch_rejected(self):

        with self.assertRaises(ValueError):
            self.engine.verify(
                scope_id="tenant-b",
                subject_reference="foreign",
                expected_outcome_ids=(
                    "expected-1",
                ),
                observed_outcomes=(),
                evidence_ids=(),
            )

    # ========================================================================
    # Evidence registration
    # ========================================================================

    def test_duplicate_evidence_rejected(self):

        evidence = IndependentEvidence(
            evidence_id="duplicate-evidence",
            scope_id="tenant-a",
            evidence_type=EvidenceType.LOG,
            source_id="logger",
            key="x",
            value=True,
            collected_at=utc_now(),
        )

        self.engine.add_evidence(
            evidence
        )

        with self.assertRaises(ValueError):
            self.engine.add_evidence(
                evidence
            )

    # ========================================================================
    # Result integrity
    # ========================================================================

    def test_result_hash(self):

        observation = ObservedOutcome(
            observation_id="hash-observation",
            scope_id="tenant-a",
            key="security_state",
            observed_value="protected",
            observed_at=utc_now(),
            source_id="sensor",
        )

        result = self.engine.verify(
            scope_id="tenant-a",
            subject_reference="hash-test",
            expected_outcome_ids=(
                "expected-1",
            ),
            observed_outcomes=(
                observation,
            ),
            evidence_ids=(),
        )

        self.assertTrue(
            self.engine.validate_result_hash(
                result
            )
        )

    # ========================================================================
    # History
    # ========================================================================

    def test_history(self):

        observation = ObservedOutcome(
            observation_id="history-observation",
            scope_id="tenant-a",
            key="security_state",
            observed_value="protected",
            observed_at=utc_now(),
            source_id="sensor",
        )

        self.engine.verify(
            scope_id="tenant-a",
            subject_reference="history-action",
            expected_outcome_ids=(
                "expected-1",
            ),
            observed_outcomes=(
                observation,
            ),
            evidence_ids=(),
        )

        history = self.engine.history(
            "history-action"
        )

        self.assertEqual(
            len(history),
            1,
        )

    # ========================================================================
    # Validation
    # ========================================================================

    def test_validation_clean(self):

        self.assertEqual(
            self.engine.validate(),
            [],
        )


# ============================================================================
# TEST RUNNER
# ============================================================================

def run_phase14_tests() -> None:

    suite = unittest.defaultTestLoader.loadTestsFromTestCase(
        Phase14Tests
    )

    result = unittest.TextTestRunner(
        verbosity=2
    ).run(suite)

    if not result.wasSuccessful():
        raise AssertionError(
            "Phase 14 verification failed"
        )


if __name__ == "__main__":
    run_phase14_tests()
