class Phase16Tests(unittest.TestCase):

    def setUp(self):

        self.engine = (
            CyberExperimentEngine()
        )

        self.target = ExperimentTarget(
            target_id="simulated-endpoint",
            scope_id="scope-a",
            target_type="endpoint",
            simulated_only=True,
        )

        self.engine.add_target(
            self.target
        )

        self.scenario = ExperimentScenario(
            scenario_id="scenario-1",
            scope_id="scope-a",
            scenario_type=ScenarioType.DEFENSIVE_RESPONSE,
            name="Controlled response test",
            description="Simulated defensive response",
            target_ids=(
                "simulated-endpoint",
            ),
            maximum_steps=4,
        )

        self.engine.add_scenario(
            self.scenario
        )

        self.step = ExperimentStep(
            step_id="step-1",
            scenario_id="scenario-1",
            sequence=0,
            operation="SIMULATE_CONTROL",
            expected_result="expected-control-result",
        )

        self.engine.add_step(
            self.step
        )

    # ========================================================================
    # Target safety
    # ========================================================================

    def test_real_target_rejected(self):

        with self.assertRaises(ValueError):

            ExperimentTarget(
                target_id="real",
                scope_id="scope-a",
                target_type="endpoint",
                simulated_only=False,
            )

    # ========================================================================
    # Scenario registration
    # ========================================================================

    def test_scenario_registration(self):

        steps = self.engine.steps_for(
            "scenario-1"
        )

        self.assertEqual(
            len(steps),
            1,
        )

        self.assertEqual(
            steps[0].step_id,
            "step-1",
        )

    # ========================================================================
    # Experiment creation
    # ========================================================================

    def test_create_experiment(self):

        experiment = (
            self.engine.create_experiment(
                experiment_id="experiment-1",
                scope_id="scope-a",
                experiment_type=(
                    ExperimentType.DEFENSE
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=42,
            )
        )

        self.assertEqual(
            experiment.status,
            ExperimentStatus.CREATED,
        )

    # ========================================================================
    # Preparation
    # ========================================================================

    def test_prepare(self):

        experiment = (
            self.engine.create_experiment(
                experiment_id="experiment-prepare",
                scope_id="scope-a",
                experiment_type=(
                    ExperimentType.ATTACK
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=10,
            )
        )

        self.engine.prepare(
            experiment.experiment_id
        )

        self.assertEqual(
            experiment.status,
            ExperimentStatus.PREPARED,
        )

    # ========================================================================
    # Experiment execution
    # ========================================================================

    def test_run(self):

        experiment = (
            self.engine.create_experiment(
                experiment_id="experiment-run",
                scope_id="scope-a",
                experiment_type=(
                    ExperimentType.DEFENSE
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=42,
            )
        )

        outcome = self.engine.run(
            experiment.experiment_id
        )

        self.assertEqual(
            experiment.status,
            ExperimentStatus.COMPLETED,
        )

        self.assertEqual(
            len(outcome.step_results),
            1,
        )

        self.assertEqual(
            len(outcome.observations),
            1,
        )

    # ========================================================================
    # Deterministic seed
    # ========================================================================

    def test_seed_reproducibility(self):

        first = (
            self.engine.create_experiment(
                experiment_id="seed-one",
                scope_id="scope-a",
                experiment_type=(
                    ExperimentType.ATTACK
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=12345,
            )
        )

        second = (
            self.engine.create_experiment(
                experiment_id="seed-two",
                scope_id="scope-a",
                experiment_type=(
                    ExperimentType.ATTACK
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=12345,
            )
        )

        first_outcome = self.engine.run(
            first.experiment_id
        )

        second_outcome = self.engine.run(
            second.experiment_id
        )

        self.assertEqual(
            first_outcome.step_results[0].result,
            second_outcome.step_results[0].result,
        )

        self.assertEqual(
            first_outcome.step_results[0].observed_result,
            second_outcome.step_results[0].observed_result,
        )

    # ========================================================================
    # Scope isolation
    # ========================================================================

    def test_scope_isolation(self):

        with self.assertRaises(ValueError):

            self.engine.create_experiment(
                experiment_id="foreign",
                scope_id="scope-b",
                experiment_type=(
                    ExperimentType.DEFENSE
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=1,
            )

    # ========================================================================
    # Baseline
    # ========================================================================

    def test_baseline_comparison(self):

        baseline = ExperimentBaseline(
            baseline_id="baseline-1",
            scope_id="scope-a",
            metrics=(
                ("total_steps", 1.0),
                ("passed_steps", 0.0),
                ("failed_steps", 0.0),
            ),
            created_at=utc_now(),
        )

        self.engine.add_baseline(
            baseline
        )

        experiment = (
            self.engine.create_experiment(
                experiment_id="baseline-test",
                scope_id="scope-a",
                experiment_type=(
                    ExperimentType.DEFENSE
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=42,
            )
        )

        outcome = self.engine.run(
            experiment.experiment_id,
            baseline_id="baseline-1",
        )

        comparison = (
            self.engine.compare_baseline(
                outcome.outcome_id,
                "baseline-1",
            )
        )

        self.assertIn(
            "total_steps",
            comparison,
        )

    # ========================================================================
    # Safety limits
    # ========================================================================

    def test_step_limit(self):

        limited = (
            ExperimentSafetyLimits(
                maximum_steps=1,
                maximum_observations=10,
                maximum_targets=2,
            )
        )

        experiment = (
            self.engine.create_experiment(
                experiment_id="limited",
                scope_id="scope-a",
                experiment_type=(
                    ExperimentType.DEFENSE
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=1,
                safety_limits=limited,
            )
        )

        self.engine.prepare(
            experiment.experiment_id
        )

        self.assertEqual(
            experiment.status,
            ExperimentStatus.PREPARED,
        )

    # ========================================================================
    # Outcome integrity
    # ========================================================================

    def test_outcome_hash(self):

        experiment = (
            self.engine.create_experiment(
                experiment_id="hash-test",
                scope_id="scope-a",
                experiment_type=(
                    ExperimentType.DEFENSE
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=99,
            )
        )

        outcome = self.engine.run(
            experiment.experiment_id
        )

        self.assertTrue(
            self.engine.validate_outcome_hash(
                outcome
            )
        )

    # ========================================================================
    # Global validation
    # ========================================================================

    def test_validation(self):

        experiment = (
            self.engine.create_experiment(
                experiment_id="validation-test",
                scope_id="scope-a",
                experiment_type=(
                    ExperimentType.DEFENSE
                ),
                scenario_ids=(
                    "scenario-1",
                ),
                seed=5,
            )
        )

        self.engine.run(
            experiment.experiment_id
        )

        self.assertEqual(
            self.engine.validate(),
            [],
        )


# ============================================================================
# TEST RUNNER
# ============================================================================

def run_phase16_tests() -> None:

    suite = unittest.defaultTestLoader.loadTestsFromTestCase(
        Phase16Tests
    )

    result = unittest.TextTestRunner(
        verbosity=2
    ).run(suite)

    if not result.wasSuccessful():
        raise AssertionError(
            "Phase 16 tests failed"
        )


