from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from enum import Enum
from threading import RLock
from typing import Dict, FrozenSet, Iterable, List, Optional, Tuple
import hashlib
import unittest


# ============================================================================
# HELPERS
# ============================================================================

def utc_now() -> datetime:
    return datetime.now(timezone.utc)


def ensure_aware(value: datetime) -> datetime:
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError("datetime must be timezone-aware")
    return value


def stable_hash(*parts: object) -> str:
    material = "|".join(str(part) for part in parts)
    return hashlib.sha256(
        material.encode("utf-8")
    ).hexdigest()


# ============================================================================
# ENUMS
# ============================================================================

class LessonType(str, Enum):
    INCIDENT = "INCIDENT"
    VERIFICATION_FAILURE = "VERIFICATION_FAILURE"
    REGENERATION = "REGENERATION"
    EXPERIMENT = "EXPERIMENT"
    OUTCOME = "OUTCOME"
    OBSERVATION = "OBSERVATION"


class ControlType(str, Enum):
    BLOCK = "BLOCK"
    ISOLATE = "ISOLATE"
    RESTRICT = "RESTRICT"
    REVOKE = "REVOKE"
    SEGMENT = "SEGMENT"
    RATE_LIMIT = "RATE_LIMIT"
    MONITOR = "MONITOR"
    ALERT = "ALERT"
    HARDEN = "HARDEN"


class ControlStatus(str, Enum):
    CANDIDATE = "CANDIDATE"
    SIMULATION_REQUIRED = "SIMULATION_REQUIRED"
    SIMULATION_PASSED = "SIMULATION_PASSED"
    VALIDATION_FAILED = "VALIDATION_FAILED"
    APPROVAL_REQUIRED = "APPROVAL_REQUIRED"
    APPROVED = "APPROVED"
    DEPLOYMENT_READY = "DEPLOYMENT_READY"
    DEPLOYED = "DEPLOYED"
    VERIFICATION_REQUIRED = "VERIFICATION_REQUIRED"
    VERIFIED = "VERIFIED"
    PARTIAL = "PARTIAL"
    FAILED = "FAILED"
    ROLLED_BACK = "ROLLED_BACK"
    DISABLED = "DISABLED"


class SimulationStatus(str, Enum):
    NOT_RUN = "NOT_RUN"
    PASSED = "PASSED"
    FAILED = "FAILED"
    INCONCLUSIVE = "INCONCLUSIVE"


class ValidationStatus(str, Enum):
    NOT_VALIDATED = "NOT_VALIDATED"
    PASSED = "PASSED"
    FAILED = "FAILED"
    PARTIAL = "PARTIAL"


class ApprovalStatus(str, Enum):
    NOT_REQUESTED = "NOT_REQUESTED"
    REQUESTED = "REQUESTED"
    APPROVED = "APPROVED"
    REJECTED = "REJECTED"


class DeploymentStatus(str, Enum):
    NOT_READY = "NOT_READY"
    READY = "READY"
    REQUESTED = "REQUESTED"
    DEPLOYED = "DEPLOYED"
    FAILED = "FAILED"


class VerificationStatus(str, Enum):
    NOT_VERIFIED = "NOT_VERIFIED"
    SUCCESS = "SUCCESS"
    PARTIAL = "PARTIAL"
    FAILED = "FAILED"
    UNKNOWN = "UNKNOWN"


class AdaptationOutcome(str, Enum):
    EFFECTIVE = "EFFECTIVE"
    PARTIALLY_EFFECTIVE = "PARTIALLY_EFFECTIVE"
    INEFFECTIVE = "INEFFECTIVE"
    UNKNOWN = "UNKNOWN"


# ============================================================================
# LESSON
# ============================================================================

@dataclass(frozen=True)
class SecurityLesson:
    lesson_id: str
    scope_id: str

    lesson_type: LessonType
    source_reference: str

    observed_problem: str
    desired_outcome: str

    evidence_references: FrozenSet[str]

    confidence: float
    created_at: datetime

    def __post_init__(self) -> None:
        ensure_aware(self.created_at)

        if not self.lesson_id.strip():
            raise ValueError("lesson_id must not be empty")

        if not self.scope_id.strip():
            raise ValueError("scope_id must not be empty")

        if not self.source_reference.strip():
            raise ValueError(
                "source_reference must not be empty"
            )

        if not self.observed_problem.strip():
            raise ValueError(
                "observed_problem must not be empty"
            )

        if not self.desired_outcome.strip():
            raise ValueError(
                "desired_outcome must not be empty"
            )

        if not 0.0 <= self.confidence <= 1.0:
            raise ValueError(
                "confidence must be between 0 and 1"
            )


# ============================================================================
# DEFENSIVE CONTROL CANDIDATE
# ============================================================================

@dataclass(frozen=True)
class DefensiveControl:
    control_id: str
    scope_id: str

    control_type: ControlType

    target_reference: str
    objective: str

    parameters: Tuple[Tuple[str, str], ...]

    source_lesson_ids: FrozenSet[str]

    expected_risk_reduction: float
    expected_collateral_impact: float
    reversibility: float

    status: ControlStatus

    created_at: datetime

    control_hash: str

    def __post_init__(self) -> None:
        ensure_aware(self.created_at)

        if not self.control_id.strip():
            raise ValueError("control_id must not be empty")

        if not self.scope_id.strip():
            raise ValueError("scope_id must not be empty")

        if not self.target_reference.strip():
            raise ValueError(
                "target_reference must not be empty"
            )

        if not self.objective.strip():
            raise ValueError("objective must not be empty")

        for value in (
            self.expected_risk_reduction,
            self.expected_collateral_impact,
            self.reversibility,
        ):
            if not 0.0 <= value <= 1.0:
                raise ValueError(
                    "control metrics must be between 0 and 1"
                )

        if not self.control_hash.strip():
            raise ValueError(
                "control_hash must not be empty"
            )


