from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
from enum import Enum
from threading import RLock
from typing import Dict, FrozenSet, Iterable, List, Optional, Tuple
import hashlib
import time
import unittest


# ============================================================================
# HELPERS
# ============================================================================

def utc_now() -> datetime:
    return datetime.now(timezone.utc)


def ensure_aware(value: datetime) -> None:
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError("datetime must be timezone-aware")


def stable_hash(*parts: object) -> str:
    material = "|".join(str(part) for part in parts)
    return hashlib.sha256(
        material.encode("utf-8")
    ).hexdigest()


# ============================================================================
# ENUMS
# ============================================================================

class ResourceType(str, Enum):
    CPU = "CPU"
    MEMORY = "MEMORY"
    STORAGE = "STORAGE"
    NETWORK = "NETWORK"
    API_REQUEST = "API_REQUEST"
    MODEL_INFERENCE = "MODEL_INFERENCE"
    REASONING_STEP = "REASONING_STEP"
    TOOL_CALL = "TOOL_CALL"
    CONCURRENT_TASK = "CONCURRENT_TASK"


class ResourceState(str, Enum):
    AVAILABLE = "AVAILABLE"
    LIMITED = "LIMITED"
    EXHAUSTED = "EXHAUSTED"
    UNKNOWN = "UNKNOWN"


class LimitType(str, Enum):
    QUOTA = "QUOTA"
    BUDGET = "BUDGET"
    RATE = "RATE"
    CONCURRENCY = "CONCURRENCY"


class EnforcementAction(str, Enum):
    ALLOW = "ALLOW"
    THROTTLE = "THROTTLE"
    DEFER = "DEFER"
    REJECT = "REJECT"
    SAFE_DEGRADE = "SAFE_DEGRADE"
    SAFE_MODE = "SAFE_MODE"


class CircuitState(str, Enum):
    CLOSED = "CLOSED"
    OPEN = "OPEN"
    HALF_OPEN = "HALF_OPEN"


class DegradationLevel(str, Enum):
    NONE = "NONE"
    LEVEL_1 = "LEVEL_1"
    LEVEL_2 = "LEVEL_2"
    LEVEL_3 = "LEVEL_3"
    EMERGENCY = "EMERGENCY"


class SafeModeState(str, Enum):
    NORMAL = "NORMAL"
    ACTIVE = "ACTIVE"


class ResourceEventType(str, Enum):
    CONSUMPTION = "CONSUMPTION"
    QUOTA_REACHED = "QUOTA_REACHED"
    BUDGET_REACHED = "BUDGET_REACHED"
    RATE_LIMITED = "RATE_LIMITED"
    CIRCUIT_OPENED = "CIRCUIT_OPENED"
    CIRCUIT_CLOSED = "CIRCUIT_CLOSED"
    DEGRADATION_CHANGED = "DEGRADATION_CHANGED"
    SAFE_MODE_ENTERED = "SAFE_MODE_ENTERED"
    SAFE_MODE_EXITED = "SAFE_MODE_EXITED"


# ============================================================================
# RESOURCE QUOTA
# ============================================================================

@dataclass(frozen=True)
class ResourceQuota:

    quota_id: str
    scope_id: str
    resource_type: ResourceType

    maximum: float
    warning_threshold: float

    created_at: datetime

    def __post_init__(self) -> None:

        ensure_aware(self.created_at)

        if not self.quota_id.strip():
            raise ValueError("quota_id required")

        if not self.scope_id.strip():
            raise ValueError("scope_id required")

        if self.maximum <= 0:
            raise ValueError("maximum must be positive")

        if not 0.0 < self.warning_threshold <= 1.0:
            raise ValueError(
                "warning_threshold must be between 0 and 1"
            )


# ============================================================================
# RESOURCE BUDGET
# ============================================================================

@dataclass(frozen=True)
class ResourceBudget:

    budget_id: str
    scope_id: str
    resource_type: ResourceType

    maximum: float
    consumed: float = 0.0

    created_at: datetime = field(
        default_factory=utc_now
    )

    def __post_init__(self) -> None:

        ensure_aware(self.created_at)

        if not self.budget_id.strip():
            raise ValueError("budget_id required")

        if not self.scope_id.strip():
            raise ValueError("scope_id required")

        if self.maximum <= 0:
            raise ValueError("maximum must be positive")

        if self.consumed < 0:
            raise ValueError("consumed cannot be negative")


# ============================================================================
# RATE LIMIT
# ============================================================================

@dataclass(frozen=True)
class RateLimit:

    limit_id: str
    scope_id: str
    resource_type: ResourceType

    maximum_events: int
    window_seconds: float

    created_at: datetime = field(
        default_factory=utc_now
    )

    def __post_init__(self) -> None:

        ensure_aware(self.created_at)

        if not self.limit_id.strip():
            raise ValueError("limit_id required")

        if not self.scope_id.strip():
            raise ValueError("scope_id required")

        if self.maximum_events <= 0:
            raise ValueError(
                "maximum_events must be positive"
            )

        if self.window_seconds <= 0:
            raise ValueError(
                "window_seconds must be positive"
            )


# ============================================================================
# RESOURCE CONSUMPTION
# ============================================================================

@dataclass(frozen=True)
class ResourceConsumption:

    event_id: str
    scope_id: str
    resource_type: ResourceType

    amount: float

    source_reference: str
    occurred_at: datetime

    def __post_init__(self) -> None:

        ensure_aware(self.occurred_at)

        if not self.event_id.strip():
            raise ValueError("event_id required")

        if not self.scope_id.strip():
            raise ValueError("scope_id required")

        if self.amount <= 0:
            raise ValueError("amount must be positive")

        if not self.source_reference.strip():
            raise ValueError(
                "source_reference required"
            )


# ============================================================================
# CIRCUIT BREAKER
# ============================================================================

@dataclass
class CircuitBreaker:

    circuit_id: str
    scope_id: str
    resource_type: ResourceType

    failure_threshold: int
    recovery_timeout_seconds: float

    state: CircuitState = CircuitState.CLOSED

    consecutive_failures: int = 0
    opened_at: Optional[datetime] = None

    def __post_init__(self) -> None:

        if not self.circuit_id.strip():
            raise ValueError("circuit_id required")

        if not self.scope_id.strip():
            raise ValueError("scope_id required")

        if self.failure_threshold <= 0:
            raise ValueError(
                "failure_threshold must be positive"
            )

        if self.recovery_timeout_seconds <= 0:
            raise ValueError(
                "recovery_timeout_seconds must be positive"
            )

    def record_success(
        self,
    ) -> None:

        self.consecutive_failures = 0
        self.state = CircuitState.CLOSED
        self.opened_at = None

    def record_failure(
        self,
    ) -> None:

        self.consecutive_failures += 1

        if (
            self.consecutive_failures
            >= self.failure_threshold
        ):
            self.state = CircuitState.OPEN
            self.opened_at = utc_now()

    def can_attempt(
        self,
        now: Optional[datetime] = None,
    ) -> bool:

        if self.state == CircuitState.CLOSED:
            return True

        if self.state == CircuitState.OPEN:

            if self.opened_at is None:
                return False

            moment = now or utc_now()
            ensure_aware(moment)

            elapsed = (
                moment - self.opened_at
            ).total_seconds()

            if (
                elapsed
                >= self.recovery_timeout_seconds
            ):
                self.state = (
                    CircuitState.HALF_OPEN
                )
                return True

            return False

        return True


# ============================================================================
# DEGRADATION POLICY
# ============================================================================

@dataclass(frozen=True)
class DegradationPolicy:

    policy_id: str
    scope_id: str

    thresholds: Tuple[
        Tuple[float, DegradationLevel],
        ...]

    created_at: datetime = field(
        default_factory=utc_now
    )

    def __post_init__(self) -> None:

        ensure_aware(self.created_at)

        if not self.policy_id.strip():
            raise ValueError("policy_id required")

        if not self.scope_id.strip():
            raise ValueError("scope_id required")

        if not self.thresholds:
            raise ValueError(
                "at least one threshold required"
            )

        previous = 1.1

        for threshold, _level in self.thresholds:

            if not 0.0 <= threshold <= 1.0:
                raise ValueError(
                    "threshold must be between 0 and 1"
                )

            if threshold >= previous:
                raise ValueError(
                    "thresholds must be descending"
                )

            previous = threshold

    def level_for(
        self,
        utilization: float,
    ) -> DegradationLevel:

        utilization = max(
            0.0,
            min(1.0, utilization),
        )

        for threshold, level in self.thresholds:

            if utilization >= threshold:
                return level

        return DegradationLevel.NONE


# ============================================================================
# ENFORCEMENT DECISION
# ============================================================================

@dataclass(frozen=True)
class ResourceDecision:

    decision_id: str
    scope_id: str

    resource_type: ResourceType
    action: EnforcementAction

    utilization: float
    reason: str

    created_at: datetime

    decision_hash: str

    def __post_init__(self) -> None:

        ensure_aware(self.created_at)

        if not self.decision_id.strip():
            raise ValueError("decision_id required")

        if not self.scope_id.strip():
            raise ValueError("scope_id required")

        if not 0.0 <= self.utilization:
            raise ValueError(
                "utilization cannot be negative"
            )

        if not self.reason.strip():
            raise ValueError("reason required")

        if not self.decision_hash.strip():
            raise ValueError(
                "decision_hash required"
            )


