# ============================================================================
# ADVERSARIAL VALIDATION ENGINE
# ============================================================================

class AdversarialValidationEngine:

    """
    Phase 23 defensive validation coordinator.

    It models and validates adversarial conditions without performing
    offensive operations against real or external systems.
    """

    def __init__(self) -> None:

        self._scenarios: Dict[
            str,
            AdversarialScenario,
        ] = {}

        self._observations: Dict[
            str,
            AdversarialObservation,
        ] = {}

        self._evidence: Dict[
            str,
            ValidationEvidence,
        ] = {}

        self._controls: Dict[
            str,
            DefensiveControl,
        ] = {}

        self._mappings: Dict[
            str,
            PurpleMapping,
        ] = {}

        self._findings: Dict[
            str,
            ValidationFinding,
        ] = {}

        self._runs: Dict[
            str,
            ValidationRun,
        ] = {}

        self._lock = RLock()

    # ========================================================================
    # SCENARIOS
    # ========================================================================

    def register_scenario(
        self,
        scenario: AdversarialScenario,
    ) -> None:

        with self._lock:

            if scenario.scenario_id in (
                self._scenarios
            ):
                raise ValueError(
                    "duplicate scenario"
                )

            self._scenarios[
                scenario.scenario_id
            ] = scenario

    def get_scenario(
        self,
        scenario_id: str,
    ) -> AdversarialScenario:

        scenario = self._scenarios.get(
            scenario_id
        )

        if scenario is None:
            raise KeyError(
                "scenario not found"
            )

        return scenario

    # ========================================================================
    # CONTROLS
    # ========================================================================

    def register_control(
        self,
        control: DefensiveControl,
    ) -> None:

        with self._lock:

            if control.control_id in (
                self._controls
            ):
                raise ValueError(
                    "duplicate control"
                )

            self._controls[
                control.control_id
            ] = control

    # ========================================================================
    # PURPLE TEAM MAPPING
    # ========================================================================

    def add_purple_mapping(
        self,
        mapping: PurpleMapping,
    ) -> None:

        with self._lock:

            scenario = self.get_scenario(
                mapping.scenario_id
            )

            control = self._controls.get(
                mapping.control_id
            )

            if control is None:
                raise KeyError(
                    "control not found"
                )

            if scenario.scope_id != (
                mapping.scope_id
            ):
                raise ValueError(
                    "scenario scope mismatch"
                )

            if control.scope_id != (
                mapping.scope_id
            ):
                raise ValueError(
                    "control scope mismatch"
                )

            if scenario.scenario_type not in (
                control.supported_scenarios
            ):
                raise ValueError(
                    "control does not declare "
                    "support for scenario"
                )

            if mapping.mapping_id in (
                self._mappings
            ):
                raise ValueError(
                    "duplicate purple mapping"
                )

            self._mappings[
                mapping.mapping_id
            ] = mapping

    # ========================================================================
    # SAFETY
    # ========================================================================

    @staticmethod
    def _safe_scenario(
        scenario: AdversarialScenario,
    ) -> bool:

        return (
            not scenario.allowed_external_access
            and not scenario.production_target
            and not scenario.destructive
        )

    # ========================================================================
    # PREPARE
    # ========================================================================

    def prepare_scenario(
        self,
        scenario_id: str,
    ) -> ScenarioStatus:

        with self._lock:

            scenario = self.get_scenario(
                scenario_id
            )

            if not self._safe_scenario(
                scenario
            ):
                raise ValueError(
                    "scenario failed safety validation"
                )

            return ScenarioStatus.PREPARED

    # ========================================================================
    # VALIDATION RUN
    # ========================================================================

    def create_run(
        self,
        scope_id: str,
        scenario_ids: Iterable[str],
    ) -> ValidationRun:

        with self._lock:

            ids = list(scenario_ids)

            if not ids:
                raise ValueError(
                    "at least one scenario required"
                )

            for scenario_id in ids:

                scenario = self.get_scenario(
                    scenario_id
                )

                if scenario.scope_id != scope_id:
                    raise ValueError(
                        "scenario scope mismatch"
                    )

                if not self._safe_scenario(
                    scenario
                ):
                    raise ValueError(
                        "unsafe scenario"
                    )

            timestamp = utc_now()

            run_id = stable_hash(
                "phase23-run",
                scope_id,
                tuple(ids),
                timestamp.isoformat(),
            )

            run = ValidationRun(
                run_id=run_id,
                scope_id=scope_id,
                scenario_ids=ids,
                started_at=timestamp,
                status=ScenarioStatus.PREPARED,
            )

            run.run_hash = self._run_hash(
                run
            )

            self._runs[
                run_id
            ] = run

            return run

    # ========================================================================
    # EVIDENCE
    # ========================================================================

    def add_evidence(
        self,
        evidence: ValidationEvidence,
    ) -> None:

        with self._lock:

            self.get_scenario(
                evidence.scenario_id
            )

            if evidence.evidence_id in (
                self._evidence
            ):
                raise ValueError(
                    "duplicate evidence"
                )

            self._evidence[
                evidence.evidence_id
            ] = evidence

    # ========================================================================
    # OBSERVATION
    # ========================================================================

    def record_observation(
        self,
        run_id: str,
        observation: AdversarialObservation,
    ) -> None:

        with self._lock:

            run = self._runs.get(
                run_id
            )

            if run is None:
                raise KeyError(
                    "validation run not found"
                )

            scenario = self.get_scenario(
                observation.scenario_id
            )

            if scenario.scope_id != run.scope_id:
                raise ValueError(
                    "observation scope mismatch"
                )

            if (
                observation.scenario_id
                not in run.scenario_ids
            ):
                raise ValueError(
                    "scenario not part of run"
                )

            if observation.observation_id in (
                self._observations
            ):
                raise ValueError(
                    "duplicate observation"
                )

            for evidence_id in (
                observation.evidence_ids
            ):

                evidence = self._evidence.get(
                    evidence_id
                )

                if evidence is None:
                    raise KeyError(
                        f"evidence not found: "
                        f"{evidence_id}"
                    )

                if evidence.scenario_id != (
                    observation.scenario_id
                ):
                    raise ValueError(
                        "evidence scenario mismatch"
                    )

            self._observations[
                observation.observation_id
            ] = observation

            run.observation_ids.append(
                observation.observation_id
            )

            run.status = (
                ScenarioStatus.EXECUTED
            )

            run.run_hash = self._run_hash(
                run
            )

    # ========================================================================
    # RESULT EVALUATION
    # ========================================================================

    @staticmethod
    def _evaluate_result(
        scenario: AdversarialScenario,
        observation: AdversarialObservation,
    ) -> ValidationResultStatus:

        expected = (
            scenario.expected_defensive_outcome
        )

        actual = observation.outcome

        if observation.status == (
            ObservationStatus.UNKNOWN
        ):
            return ValidationResultStatus.UNKNOWN

        if observation.status == (
            ObservationStatus.NOT_OBSERVED
        ):
            return ValidationResultStatus.FAIL

        if actual == expected:
            return ValidationResultStatus.PASS

        if (
            actual
            in {
                DefensiveOutcome.DETECTED,
                DefensiveOutcome.CONTAINED,
                DefensiveOutcome.QUARANTINED,
                DefensiveOutcome.REJECTED,
                DefensiveOutcome.VERIFIED,
            }
            and expected
            in {
                DefensiveOutcome.CONTAINED,
                DefensiveOutcome.QUARANTINED,
                DefensiveOutcome.REJECTED,
            }
        ):
            return ValidationResultStatus.PARTIAL

        return ValidationResultStatus.FAIL

    # ========================================================================
    # FINDING
    # ========================================================================

    def evaluate_observation(
        self,
        observation_id: str,
    ) -> ValidationFinding:

        with self._lock:

            observation = self._observations.get(
                observation_id
            )

            if observation is None:
                raise KeyError(
                    "observation not found"
                )

            scenario = self.get_scenario(
                observation.scenario_id
            )

            result = self._evaluate_result(
                scenario,
                observation,
            )

            control_refs = frozenset(
                mapping.control_id
                for mapping
                in self._mappings.values()
                if mapping.scenario_id
                == scenario.scenario_id
            )

            finding_hash = stable_hash(
                "phase23-finding",
                scenario.scenario_id,
                observation.observation_id,
                result.value,
                observation.outcome.value,
                tuple(sorted(control_refs)),
                tuple(
                    sorted(
                        observation.evidence_ids
                    )
                ),
            )

            explanation = (
                f"Expected "
                f"{scenario.expected_defensive_outcome.value}; "
                f"observed "
                f"{observation.outcome.value}; "
                f"validation result "
                f"{result.value}."
            )

            finding = ValidationFinding(
                finding_id=stable_hash(
                    "finding",
                    finding_hash,
                ),
                scope_id=scenario.scope_id,
                scenario_id=scenario.scenario_id,
                result=result,
                outcome=observation.outcome,
                severity=scenario.severity,
                control_references=control_refs,
                evidence_references=(
                    observation.evidence_ids
                ),
                explanation=explanation,
                created_at=utc_now(),
                finding_hash=finding_hash,
            )

            self._findings[
                finding.finding_id
            ] = finding

            for run in self._runs.values():

                if (
                    observation_id
                    in run.observation_ids
                ):
                    run.finding_ids.append(
                        finding.finding_id
                    )

                    run.run_hash = (
                        self._run_hash(run)
                    )

            return finding

    # ========================================================================
    # RUN COMPLETION
    # ========================================================================

    def complete_run(
        self,
        run_id: str,
    ) -> ValidationRun:

        with self._lock:

            run = self._runs.get(
                run_id
            )

            if run is None:
                raise KeyError(
                    "validation run not found"
                )

            run.completed_at = utc_now()

            if any(
                self._findings[finding_id].result
                == ValidationResultStatus.FAIL
                for finding_id
                in run.finding_ids
            ):
                run.status = (
                    ScenarioStatus.FAILED
                )

            else:

                run.status = (
                    ScenarioStatus.EXECUTED
                )

            run.run_hash = self._run_hash(
                run
            )

            return run

    # ========================================================================
    # DOMAIN SUMMARY
    # ========================================================================

    def findings_by_domain(
        self,
        domain: ValidationDomain,
    ) -> Tuple[
        ValidationFinding,
        ...,
    ]:

        with self._lock:

            scenario_ids = {
                scenario.scenario_id
                for scenario
                in self._scenarios.values()
                if scenario.domain == domain
            }

            return tuple(
                finding
                for finding
                in self._findings.values()
                if finding.scenario_id
                in scenario_ids
            )

    # ========================================================================
    # LOOKUPS
    # ========================================================================

    def get_finding(
        self,
        finding_id: str,
    ) -> ValidationFinding:

        finding = self._findings.get(
            finding_id
        )

        if finding is None:
            raise KeyError(
                "finding not found"
            )

        return finding

    def get_run(
        self,
        run_id: str,
    ) -> ValidationRun:

        run = self._runs.get(
            run_id
        )

        if run is None:
            raise KeyError(
                "validation run not found"
            )

        return run

    # ========================================================================
    # VALIDATION
    # ========================================================================

    def validate(self) -> List[str]:

        errors: List[str] = []

        with self._lock:

            for scenario_id, scenario in (
                self._scenarios.items()
            ):

                if scenario_id != scenario.scenario_id:
                    errors.append(
                        "scenario key mismatch"
                    )

                if not self._safe_scenario(
                    scenario
                ):
                    errors.append(
                        f"unsafe scenario stored: "
                        f"{scenario_id}"
                    )

            for evidence_id, evidence in (
                self._evidence.items()
            ):

                if evidence_id != evidence.evidence_id:
                    errors.append(
                        "evidence key mismatch"
                    )

                if evidence.scenario_id not in (
                    self._scenarios
                ):
                    errors.append(
                        f"evidence references "
                        f"unknown scenario: "
                        f"{evidence_id}"
                    )

            for observation_id, observation in (
                self._observations.items()
            ):

                if (
                    observation_id
                    != observation.observation_id
                ):
                    errors.append(
                        "observation key mismatch"
                    )

                if observation.scenario_id not in (
                    self._scenarios
                ):
                    errors.append(
                        f"observation references "
                        f"unknown scenario: "
                        f"{observation_id}"
                    )

                for evidence_id in (
                    observation.evidence_ids
                ):

                    if evidence_id not in (
                        self._evidence
                    ):
                        errors.append(
                            f"observation references "
                            f"unknown evidence: "
                            f"{evidence_id}"
                        )

            for mapping_id, mapping in (
                self._mappings.items()
            ):

                if mapping_id != mapping.mapping_id:
                    errors.append(
                        "mapping key mismatch"
                    )

                if mapping.scenario_id not in (
                    self._scenarios
                ):
                    errors.append(
                        f"mapping references "
                        f"unknown scenario: "
                        f"{mapping_id}"
                    )

                if mapping.control_id not in (
                    self._controls
                ):
                    errors.append(
                        f"mapping references "
                        f"unknown control: "
                        f"{mapping_id}"
                    )

            for finding_id, finding in (
                self._findings.items()
            ):

                if finding_id != finding.finding_id:
                    errors.append(
                        "finding key mismatch"
                    )

                if finding.scenario_id not in (
                    self._scenarios
                ):
                    errors.append(
                        f"finding references "
                        f"unknown scenario: "
                        f"{finding_id}"
                    )

                for evidence_id in (
                    finding.evidence_references
                ):

                    if evidence_id not in (
                        self._evidence
                    ):
                        errors.append(
                            f"finding references "
                            f"unknown evidence: "
                            f"{evidence_id}"
                        )

                for control_id in (
                    finding.control_references
                ):

                    if control_id not in (
                        self._controls
                    ):
                        errors.append(
                            f"finding references "
                            f"unknown control: "
                            f"{control_id}"
                        )

            for run_id, run in (
                self._runs.items()
            ):

                if run_id != run.run_id:
                    errors.append(
                        "run key mismatch"
                    )

                for scenario_id in (
                    run.scenario_ids
                ):

                    if scenario_id not in (
                        self._scenarios
                    ):
                        errors.append(
                            f"run references "
                            f"unknown scenario: "
                            f"{scenario_id}"
                        )

                for observation_id in (
                    run.observation_ids
                ):

                    if observation_id not in (
                        self._observations
                    ):
                        errors.append(
                            f"run references "
                            f"unknown observation: "
                            f"{observation_id}"
                        )

                for finding_id in (
                    run.finding_ids
                ):

                    if finding_id not in (
                        self._findings
                    ):
                        errors.append(
                            f"run references "
                            f"unknown finding: "
                            f"{finding_id}"
                        )

        return errors

    # ========================================================================
    # HASH
    # ========================================================================

    @staticmethod
    def _run_hash(
        run: ValidationRun,
    ) -> str:

        return stable_hash(
            run.run_id,
            run.scope_id,
            tuple(run.scenario_ids),
            tuple(run.observation_ids),
            tuple(run.finding_ids),
            run.status.value,
            (
                run.started_at.isoformat()
                if run.started_at
                else None
            ),
            (
                run.completed_at.isoformat()
                if run.completed_at
                else None
            ),
        )


