class Phase23Tests(unittest.TestCase):

    def setUp(self):

        self.scope = "validation-tenant"

        self.engine = (
            AdversarialValidationEngine()
        )

        self.scenario = AdversarialScenario(
            scenario_id="agent-injection-1",
            scope_id=self.scope,
            domain=ValidationDomain.AGENT_SECURITY,
            scenario_type=(
                ScenarioType.PROMPT_INJECTION
            ),
            severity=ScenarioSeverity.HIGH,
            target_component=(
                "phase19-agent-self-protection"
            ),
            description=(
                "controlled prompt-injection "
                "validation scenario"
            ),
            expected_defensive_outcome=(
                DefensiveOutcome.DETECTED
            ),
        )

        self.engine.register_scenario(
            self.scenario
        )

        self.control = DefensiveControl(
            control_id="agent-control-1",
            scope_id=self.scope,
            control_name=(
                "AI self-protection detection"
            ),
            component_reference=(
                "phase19"
            ),
            supported_scenarios=frozenset(
                {
                    ScenarioType.PROMPT_INJECTION,
                    ScenarioType.GOAL_HIJACKING,
                }
            ),
        )

        self.engine.register_control(
            self.control
        )

    # ========================================================================
    # Safety
    # ========================================================================

    def test_safe_scenario(self):

        status = (
            self.engine.prepare_scenario(
                self.scenario.scenario_id
            )
        )

        self.assertEqual(
            status,
            ScenarioStatus.PREPARED,
        )

    # ========================================================================
    # Purple mapping
    # ========================================================================

    def test_purple_mapping(self):

        mapping = PurpleMapping(
            mapping_id="mapping-1",
            scope_id=self.scope,
            scenario_id=self.scenario.scenario_id,
            control_id=self.control.control_id,
            expected_outcome=(
                DefensiveOutcome.DETECTED
            ),
        )

        self.engine.add_purple_mapping(
            mapping
        )

        self.assertEqual(
            len(
                self.engine._mappings
            ),
            1,
        )

    # ========================================================================
    # Run
    # ========================================================================

    def test_validation_run(self):

        run = self.engine.create_run(
            self.scope,
            [self.scenario.scenario_id],
        )

        self.assertEqual(
            run.status,
            ScenarioStatus.PREPARED,
        )

    # ========================================================================
    # Evidence
    # ========================================================================

    def test_evidence_and_observation(self):

        evidence = ValidationEvidence(
            evidence_id="evidence-1",
            scenario_id=self.scenario.scenario_id,
            kind=EvidenceKind.AGENT,
            source_reference="agent-monitor",
            content_reference="observation-record-1",
            integrity_valid=True,
            independent=True,
        )

        self.engine.add_evidence(
            evidence
        )

        run = self.engine.create_run(
            self.scope,
            [self.scenario.scenario_id],
        )

        observation = AdversarialObservation(
            observation_id="observation-1",
            scenario_id=self.scenario.scenario_id,
            status=ObservationStatus.OBSERVED,
            outcome=DefensiveOutcome.DETECTED,
            detection_reference=(
                "phase19-indicator-1"
            ),
            defensive_reference=(
                "phase19-decision-1"
            ),
            evidence_ids=frozenset(
                {"evidence-1"}
            ),
            confidence=0.90,
            summary=(
                "controlled detection observed"
            ),
            observed_at=utc_now(),
        )

        self.engine.record_observation(
            run.run_id,
            observation,
        )

        finding = (
            self.engine.evaluate_observation(
                observation.observation_id
            )
        )

        self.assertEqual(
            finding.result,
            ValidationResultStatus.PASS,
        )

    # ========================================================================
    # Failure
    # ========================================================================

    def test_failed_detection(self):

        run = self.engine.create_run(
            self.scope,
            [self.scenario.scenario_id],
        )

        observation = AdversarialObservation(
            observation_id="observation-fail",
            scenario_id=self.scenario.scenario_id,
            status=ObservationStatus.NOT_OBSERVED,
            outcome=DefensiveOutcome.NOT_DETECTED,
            detection_reference=None,
            defensive_reference=None,
            evidence_ids=frozenset(),
            confidence=0.95,
            summary=(
                "expected defensive detection "
                "was not observed"
            ),
            observed_at=utc_now(),
        )

        self.engine.record_observation(
            run.run_id,
            observation,
        )

        finding = (
            self.engine.evaluate_observation(
                observation.observation_id
            )
        )

        self.assertEqual(
            finding.result,
            ValidationResultStatus.FAIL,
        )

    # ========================================================================
    # Unknown
    # ========================================================================

    def test_unknown_observation(self):

        run = self.engine.create_run(
            self.scope,
            [self.scenario.scenario_id],
        )

        observation = AdversarialObservation(
            observation_id="observation-unknown",
            scenario_id=self.scenario.scenario_id,
            status=ObservationStatus.UNKNOWN,
            outcome=DefensiveOutcome.UNKNOWN,
            detection_reference=None,
            defensive_reference=None,
            evidence_ids=frozenset(),
            confidence=0.20,
            summary="insufficient evidence",
            observed_at=utc_now(),
        )

        self.engine.record_observation(
            run.run_id,
            observation,
        )

        finding = (
            self.engine.evaluate_observation(
                observation.observation_id
            )
        )

        self.assertEqual(
            finding.result,
            ValidationResultStatus.UNKNOWN,
        )

    # ========================================================================
    # Domain filtering
    # ========================================================================

    def test_domain_filter(self):

        run = self.engine.create_run(
            self.scope,
            [self.scenario.scenario_id],
        )

        observation = AdversarialObservation(
            observation_id="observation-domain",
            scenario_id=self.scenario.scenario_id,
            status=ObservationStatus.OBSERVED,
            outcome=DefensiveOutcome.DETECTED,
            detection_reference="detection",
            defensive_reference="defense",
            evidence_ids=frozenset(),
            confidence=0.85,
            summary="detected",
            observed_at=utc_now(),
        )

        self.engine.record_observation(
            run.run_id,
            observation,
        )

        self.engine.evaluate_observation(
            observation.observation_id
        )

        findings = (
            self.engine.findings_by_domain(
                ValidationDomain.AGENT_SECURITY
            )
        )

        self.assertEqual(
            len(findings),
            1,
        )

    # ========================================================================
    # Validation
    # ========================================================================

    def test_global_validation(self):

        self.assertEqual(
            self.engine.validate(),
            [],
        )


# ============================================================================
# TEST RUNNER
# ============================================================================

def run_phase23_tests() -> None:

    suite = (
        unittest.defaultTestLoader
        .loadTestsFromTestCase(
            Phase23Tests
        )
    )

    result = unittest.TextTestRunner(
        verbosity=2
    ).run(suite)

    if not result.wasSuccessful():
        raise AssertionError(
            "Phase 23 tests failed"
        )


if __name__ == "__main__":
    run_phase23_tests()
