# ENUMS
# ============================================================================

class BenchmarkDomain(str, Enum):

    SECURITY_STATE = "SECURITY_STATE"
    STATE_INTEGRITY = "STATE_INTEGRITY"
    ATTACK_PATH = "ATTACK_PATH"
