# ============================================================================
# BENCHMARK DEFINITION
# ============================================================================

@dataclass(frozen=True)
class BenchmarkDefinition:

    benchmark_id: str
    scope_id: str

    name: str
    domain: BenchmarkDomain

    objective: str

    metric_name: str
    metric_type: MeasurementType
    direction: MetricDirection

    repetitions: int

    seed: int

    version: str

    created_at: datetime = field(
        default_factory=utc_now
    )

    definition_hash: str = ""

    def __post_init__(self) -> None:

        ensure_aware(self.created_at)

        if not self.benchmark_id.strip():
            raise ValueError(
                "benchmark_id required"
            )

        if not self.scope_id.strip():
            raise ValueError(
                "scope_id required"
            )

        if not self.name.strip():
            raise ValueError(
                "benchmark name required"
            )

        if not self.objective.strip():
            raise ValueError(
                "objective required"
            )

        if not self.metric_name.strip():
            raise ValueError(
                "metric_name required"
            )

        if self.repetitions <= 0:
            raise ValueError(
                "repetitions must be > 0"
            )

        if not self.version.strip():
            raise ValueError(
                "version required"
            )


# ============================================================================
# BASELINE
# ============================================================================

@dataclass(frozen=True)
class BenchmarkBaseline:

    baseline_id: str
    benchmark_id: str

    name: str

    values: Tuple[float, ...]

    source_reference: str

    created_at: datetime = field(
        default_factory=utc_now
    )

    baseline_hash: str = ""

    def __post_init__(self) -> None:

        ensure_aware(self.created_at)

        if not self.baseline_id.strip():
            raise ValueError(
                "baseline_id required"
            )

        if not self.benchmark_id.strip():
            raise ValueError(
                "benchmark_id required"
            )

        if not self.name.strip():
            raise ValueError(
                "baseline name required"
            )

        if not self.values:
            raise ValueError(
                "baseline requires values"
            )

        if not self.source_reference.strip():
            raise ValueError(
                "source_reference required"
            )

        if any(
            value != value
            for value in self.values
        ):
            raise ValueError(
                "NaN values are not allowed"
            )


# ============================================================================
# EXPERIMENT
# ============================================================================

@dataclass(frozen=True)
class BenchmarkExperiment:

    experiment_id: str
    benchmark_id: str

    configuration: Tuple[
        Tuple[str, str],
        ...
    ]

    isolation_label: str

    seed: int

    created_at: datetime = field(
        default_factory=utc_now
    )

    experiment_hash: str = ""

    def __post_init__(self) -> None:

        ensure_aware(self.created_at)

        if not self.experiment_id.strip():
            raise ValueError(
                "experiment_id required"
            )

        if not self.benchmark_id.strip():
            raise ValueError(
                "benchmark_id required"
            )

        if not self.isolation_label.strip():
            raise ValueError(
                "isolation_label required"
            )


# ============================================================================
# TRIAL
# ============================================================================

@dataclass(frozen=True)
class BenchmarkTrial:

    trial_id: str
    experiment_id: str

    repetition: int

    metric_value: float

    status: TrialStatus

    seed: int

    execution_reference: str

    failure_category: Optional[
        FailureCategory
    ] = None

    failure_reason: Optional[str] = None

    created_at: datetime = field(
        default_factory=utc_now
    )

    trial_hash: str = ""

    def __post_init__(self) -> None:

        ensure_aware(self.created_at)

        if not self.trial_id.strip():
            raise ValueError(
                "trial_id required"
            )

        if not self.experiment_id.strip():
            raise ValueError(
                "experiment_id required"
            )

        if self.repetition <= 0:
            raise ValueError(
                "repetition must be > 0"
            )

        if self.metric_value != (
            self.metric_value
        ):
            raise ValueError(
                "NaN metric value"
            )

        if not self.execution_reference.strip():
            raise ValueError(
                "execution_reference required"
            )

        if (
            self.status == TrialStatus.FAILED
            and self.failure_category is None
        ):
            raise ValueError(
                "failed trial requires failure category"
            )


