# ============================================================================
# SCIENTIFIC BENCHMARKING ENGINE
# ============================================================================

class ScientificBenchmarkingEngine:

    """
    Phase 24 benchmark coordinator.

    The engine measures supplied experiment results and computes
    reproducible statistical summaries. It does not perform attacks
    or production deployment.
    """

    CONFIDENCE_Z_95 = 1.96

    def __init__(self) -> None:

        self._benchmarks: Dict[
            str,
            BenchmarkDefinition,
        ] = {}

        self._baselines: Dict[
            str,
            BenchmarkBaseline,
        ] = {}

        self._experiments: Dict[
            str,
            BenchmarkExperiment,
        ] = {}

        self._trials: Dict[
            str,
            BenchmarkTrial,
        ] = {}

        self._summaries: Dict[
            str,
            StatisticalSummary,
        ] = {}

        self._comparisons: Dict[
            str,
            BenchmarkComparison,
        ] = {}

        self._failures: Dict[
            str,
            FailureAnalysis,
        ] = {}

        self._reproducibility: Dict[
            str,
            ReproducibilityRecord,
        ] = {}

        self._runs: Dict[
            str,
            BenchmarkRun,
        ] = {}

        self._lock = RLock()

    # ========================================================================
    # BENCHMARK
    # ========================================================================

    def register_benchmark(
        self,
        benchmark: BenchmarkDefinition,
    ) -> None:

        with self._lock:

            if benchmark.benchmark_id in (
                self._benchmarks
            ):
                raise ValueError(
                    "duplicate benchmark"
                )

            self._benchmarks[
                benchmark.benchmark_id
            ] = benchmark

    def get_benchmark(
        self,
        benchmark_id: str,
    ) -> BenchmarkDefinition:

        benchmark = self._benchmarks.get(
            benchmark_id
        )

        if benchmark is None:
            raise KeyError(
                "benchmark not found"
            )

        return benchmark

    # ========================================================================
    # BASELINE
    # ========================================================================

    def register_baseline(
        self,
        baseline: BenchmarkBaseline,
    ) -> None:

        with self._lock:

            self.get_benchmark(
                baseline.benchmark_id
            )

            if baseline.baseline_id in (
                self._baselines
            ):
                raise ValueError(
                    "duplicate baseline"
                )

            self._baselines[
                baseline.baseline_id
            ] = baseline

    # ========================================================================
    # EXPERIMENT
    # ========================================================================

    def register_experiment(
        self,
        experiment: BenchmarkExperiment,
    ) -> None:

        with self._lock:

            self.get_benchmark(
                experiment.benchmark_id
            )

            if experiment.experiment_id in (
                self._experiments
            ):
                raise ValueError(
                    "duplicate experiment"
                )

            self._experiments[
                experiment.experiment_id
            ] = experiment

    # ========================================================================
    # TRIAL
    # ========================================================================

    def record_trial(
        self,
        trial: BenchmarkTrial,
    ) -> None:

        with self._lock:

            experiment = self._experiments.get(
                trial.experiment_id
            )

            if experiment is None:
                raise KeyError(
                    "experiment not found"
                )

            if trial.trial_id in (
                self._trials
            ):
                raise ValueError(
                    "duplicate trial"
                )

            benchmark = self.get_benchmark(
                experiment.benchmark_id
            )

            if trial.repetition > (
                benchmark.repetitions
            ):
                raise ValueError(
                    "repetition exceeds benchmark definition"
                )

            self._trials[
                trial.trial_id
            ] = trial

    # ========================================================================
    # SUMMARY
    # ========================================================================

    def summarize_experiment(
        self,
        experiment_id: str,
    ) -> StatisticalSummary:

        with self._lock:

            experiment = self._experiments.get(
                experiment_id
            )

            if experiment is None:
                raise KeyError(
                    "experiment not found"
                )

            values = [
                trial.metric_value
                for trial
                in self._trials.values()
                if (
                    trial.experiment_id
                    == experiment_id
                    and trial.status
                    == TrialStatus.COMPLETED
                )
            ]

            if not values:
                raise ValueError(
                    "no completed trials"
                )

            count = len(values)

            average = mean(values)

            median_value = median(values)

            minimum = min(values)
            maximum = max(values)

            if count > 1:
                deviation = stdev(values)
                standard_error = (
                    deviation
                    / sqrt(count)
                )

                margin = (
                    self.CONFIDENCE_Z_95
                    * standard_error
                )

            else:
                deviation = 0.0
                standard_error = 0.0
                margin = 0.0

            summary = StatisticalSummary(
                count=count,
                minimum=minimum,
                maximum=maximum,
                average=average,
                median_value=median_value,
                standard_deviation=deviation,
                standard_error=standard_error,
                confidence_interval_low=(
                    average - margin
                ),
                confidence_interval_high=(
                    average + margin
                ),
            )

            object.__setattr__(
                summary,
                "summary_hash",
                stable_hash(
                    experiment_id,
                    tuple(values),
                    summary.count,
                    summary.average,
                    summary.standard_deviation,
                    summary.confidence_interval_low,
                    summary.confidence_interval_high,
                ),
            )

            self._summaries[
                experiment_id
            ] = summary

            return summary

    # ========================================================================
    # COMPARISON
    # ========================================================================

    def compare_with_baseline(
        self,
        experiment_id: str,
        baseline_id: str,
    ) -> BenchmarkComparison:

        with self._lock:

            experiment = self._experiments.get(
                experiment_id
            )

            if experiment is None:
                raise KeyError(
                    "experiment not found"
                )

            baseline = self._baselines.get(
                baseline_id
            )

            if baseline is None:
                raise KeyError(
                    "baseline not found"
                )

            if baseline.benchmark_id != (
                experiment.benchmark_id
            ):
                raise ValueError(
                    "benchmark mismatch"
                )

            experiment_summary = (
                self._summaries.get(
                    experiment_id
                )
            )

            if experiment_summary is None:
                experiment_summary = (
                    self.summarize_experiment(
                        experiment_id
                    )
                )

            baseline_mean = mean(
                baseline.values
            )

            experiment_mean = (
                experiment_summary.average
            )

            delta = (
                experiment_mean
                - baseline_mean
            )

            relative_delta = (
                delta / abs(baseline_mean)
                if baseline_mean != 0
                else None
            )

            tolerance = max(
                1e-12,
                abs(baseline_mean) * 1e-9,
            )

            if abs(delta) <= tolerance:

                status = (
                    ComparisonStatus.EQUAL
                )

            elif (
                experiment_mean > baseline_mean
            ):

                status = (
                    ComparisonStatus.BETTER
                    if (
                        self.get_benchmark(
                            experiment.benchmark_id
                        ).direction
                        == MetricDirection.HIGHER_BETTER
                    )
                    else ComparisonStatus.WORSE
                )

            else:

                status = (
                    ComparisonStatus.BETTER
                    if (
                        self.get_benchmark(
                            experiment.benchmark_id
                        ).direction
                        == MetricDirection.LOWER_BETTER
                    )
                    else ComparisonStatus.WORSE
                )

            effect_ratio = (
                experiment_mean
                / baseline_mean
                if baseline_mean != 0
                else None
            )

            comparison_hash = stable_hash(
                experiment_id,
                baseline_id,
                baseline_mean,
                experiment_mean,
                delta,
                relative_delta,
                status.value,
            )

            comparison = BenchmarkComparison(
                comparison_id=stable_hash(
                    "comparison",
                    comparison_hash,
                ),
                benchmark_id=(
                    experiment.benchmark_id
                ),
                baseline_mean=baseline_mean,
                experiment_mean=experiment_mean,
                absolute_delta=delta,
                relative_delta=relative_delta,
                direction=(
                    self.get_benchmark(
                        experiment.benchmark_id
                    ).direction
                ),
                status=status,
                effect_ratio=effect_ratio,
                comparison_hash=comparison_hash,
            )

            self._comparisons[
                comparison.comparison_id
            ] = comparison

            return comparison

    # ========================================================================
    # FAILURE ANALYSIS
    # ========================================================================

    def record_failure(
        self,
        failure: FailureAnalysis,
    ) -> None:

        with self._lock:

            if failure.failure_id in (
                self._failures
            ):
                raise ValueError(
                    "duplicate failure"
                )

            experiment = self._experiments.get(
                failure.experiment_id
            )

            if experiment is None:
                raise KeyError(
                    "experiment not found"
                )

            trial = self._trials.get(
                failure.trial_id
            )

            if trial is None:
                raise KeyError(
                    "trial not found"
                )

            if trial.experiment_id != (
                failure.experiment_id
            ):
                raise ValueError(
                    "trial/experiment mismatch"
                )

            if (
                self.get_benchmark(
                    experiment.benchmark_id
                ).benchmark_id
                != failure.benchmark_id
            ):
                raise ValueError(
                    "benchmark mismatch"
                )

            self._failures[
                failure.failure_id
            ] = failure

    # ========================================================================
    # REPRODUCIBILITY
    # ========================================================================

    @staticmethod
    def deterministic_trial_values(
        seed: int,
        count: int,
    ) -> Tuple[float, ...]:

        if count <= 0:
            raise ValueError(
                "count must be > 0"
            )

        generator = random.Random(
            seed
        )

        return tuple(
            round(
                generator.random(),
                12,
            )
            for _ in range(count)
        )

    def record_reproducibility(
        self,
        experiment_id: str,
        original_values: Iterable[float],
        replay_values: Iterable[float],
        seed: int,
    ) -> ReproducibilityRecord:

        with self._lock:

            if experiment_id not in (
                self._experiments
            ):
                raise KeyError(
                    "experiment not found"
                )

            original = tuple(
                original_values
            )

            replay = tuple(
                replay_values
            )

            identical = (
                original == replay
            )

            record_material = stable_hash(
                experiment_id,
                original,
                replay,
                seed,
                identical,
            )

            record = ReproducibilityRecord(
                record_id=stable_hash(
                    "reproducibility",
                    record_material,
                ),
                experiment_id=experiment_id,
                original_values=original,
                replay_values=replay,
                identical=identical,
                seed=seed,
                record_hash=record_material,
            )

            self._reproducibility[
                record.record_id
            ] = record

            return record

    # ========================================================================
    # RUN
    # ========================================================================

    def create_run(
        self,
        benchmark_id: str,
        experiment_ids: Iterable[str],
    ) -> BenchmarkRun:

        with self._lock:

            self.get_benchmark(
                benchmark_id
            )

            ids = list(
                experiment_ids
            )

            if not ids:
                raise ValueError(
                    "experiment_ids required"
                )

            for experiment_id in ids:

                experiment = (
                    self._experiments.get(
                        experiment_id
                    )
                )

                if experiment is None:
                    raise KeyError(
                        "experiment not found"
                    )

                if experiment.benchmark_id != (
                    benchmark_id
                ):
                    raise ValueError(
                        "experiment benchmark mismatch"
                    )

            run_id = stable_hash(
                "benchmark-run",
                benchmark_id,
                tuple(ids),
                utc_now().isoformat(),
            )

            run = BenchmarkRun(
                run_id=run_id,
                benchmark_id=benchmark_id,
                experiment_ids=ids,
                status=BenchmarkStatus.PREPARED,
            )

            run.run_hash = self._run_hash(
                run
            )

            self._runs[
                run_id
            ] = run

            return run

    def complete_run(
        self,
        run_id: str,
    ) -> BenchmarkRun:

        with self._lock:

            run = self._runs.get(
                run_id
            )

            if run is None:
                raise KeyError(
                    "run not found"
                )

            for experiment_id in (
                run.experiment_ids
            ):

                self.summarize_experiment(
                    experiment_id
                )

            run.status = (
                BenchmarkStatus.COMPLETED
            )

            run.completed_at = utc_now()

            run.run_hash = self._run_hash(
                run
            )

            return run

    @staticmethod
    def _run_hash(
        run: BenchmarkRun,
    ) -> str:

        return stable_hash(
            run.run_id,
            run.benchmark_id,
            tuple(run.experiment_ids),
            run.status.value,
            (
                run.created_at.isoformat()
                if run.created_at
                else None
            ),
            (
                run.completed_at.isoformat()
                if run.completed_at
                else None
            ),
        )

    # ========================================================================
    # QUERIES
    # ========================================================================

    def get_summary(
        self,
        experiment_id: str,
    ) -> StatisticalSummary:

        summary = self._summaries.get(
            experiment_id
        )

        if summary is None:
            raise KeyError(
                "summary not found"
            )

        return summary

    def failures_for_benchmark(
        self,
        benchmark_id: str,
    ) -> Tuple[
        FailureAnalysis,
        ...
    ]:

        result = []

        for failure in (
            self._failures.values()
        ):

            if failure.benchmark_id == (
                benchmark_id
            ):
                result.append(
                    failure
                )

        return tuple(result)

    # ========================================================================
    # GLOBAL VALIDATION
    # ========================================================================

    def validate(self) -> List[str]:

        errors: List[str] = []

        with self._lock:

            for benchmark_id, benchmark in (
                self._benchmarks.items()
            ):

                if (
                    benchmark_id
                    != benchmark.benchmark_id
                ):
                    errors.append(
                        "benchmark key mismatch"
                    )

            for baseline_id, baseline in (
                self._baselines.items()
            ):

                if (
                    baseline_id
                    != baseline.baseline_id
                ):
                    errors.append(
                        "baseline key mismatch"
                    )

                if baseline.benchmark_id not in (
                    self._benchmarks
                ):
                    errors.append(
                        f"baseline references "
                        f"unknown benchmark: "
                        f"{baseline_id}"
                    )

            for experiment_id, experiment in (
                self._experiments.items()
            ):

                if (
                    experiment_id
                    != experiment.experiment_id
                ):
                    errors.append(
                        "experiment key mismatch"
                    )

                if experiment.benchmark_id not in (
                    self._benchmarks
                ):
                    errors.append(
                        f"experiment references "
                        f"unknown benchmark: "
                        f"{experiment_id}"
                    )

            for trial_id, trial in (
                self._trials.items()
            ):

                if (
                    trial_id
                    != trial.trial_id
                ):
                    errors.append(
                        "trial key mismatch"
                    )

                if trial.experiment_id not in (
                    self._experiments
                ):
                    errors.append(
                        f"trial references "
                        f"unknown experiment: "
                        f"{trial_id}"
                    )

            for failure_id, failure in (
                self._failures.items()
            ):

                if (
                    failure_id
                    != failure.failure_id
                ):
                    errors.append(
                        "failure key mismatch"
                    )

                if failure.experiment_id not in (
                    self._experiments
                ):
                    errors.append(
                        f"failure references "
                        f"unknown experiment: "
                        f"{failure_id}"
                    )

                if failure.trial_id not in (
                    self._trials
                ):
                    errors.append(
                        f"failure references "
                        f"unknown trial: "
                        f"{failure_id}"
                    )

            for run_id, run in (
                self._runs.items()
            ):

                if run_id != run.run_id:
                    errors.append(
                        "run key mismatch"
                    )

                if run.benchmark_id not in (
                    self._benchmarks
                ):
                    errors.append(
                        f"run references "
                        f"unknown benchmark: "
                        f"{run_id}"
                    )

        return errors


# ============================================================================
# PHASE 24 TESTS
# ============================================================================

class Phase24Tests(unittest.TestCase):

    def setUp(self):

        self.scope = "benchmark-scope"

        self.engine = (
            ScientificBenchmarkingEngine()
        )

        self.benchmark = BenchmarkDefinition(
            benchmark_id="benchmark-1",
            scope_id=self.scope,
            name="Detection Benchmark",
            domain=BenchmarkDomain.AI_PROTECTION,
            objective=(
                "Measure defensive detection rate"
            ),
            metric_name="detection_rate",
            metric_type=(
                MeasurementType.DETECTION_RATE
            ),
            direction=(
                MetricDirection.HIGHER_BETTER
            ),
            repetitions=4,
            seed=42,
            version="1.0",
        )

        self.engine.register_benchmark(
            self.benchmark
        )

    # ========================================================================
    # Registration
    # ========================================================================

    def test_registration(self):

        self.assertEqual(
            self.engine.get_benchmark(
                "benchmark-1"
            ).name,
            "Detection Benchmark",
        )

    # ========================================================================
    # Baseline
    # ========================================================================

    def test_baseline(self):

        baseline = BenchmarkBaseline(
            baseline_id="baseline-1",
            benchmark_id="benchmark-1",
            name="Baseline",
            values=(
                0.60,
                0.62,
                0.61,
                0.59,
            ),
            source_reference="controlled-baseline",
        )

        self.engine.register_baseline(
            baseline
        )

        self.assertEqual(
            len(self.engine._baselines),
            1,
        )

    # ========================================================================
    # Experiment + trials
    # ========================================================================

    def test_experiment_summary(self):

        experiment = BenchmarkExperiment(
            experiment_id="experiment-1",
            benchmark_id="benchmark-1",
            configuration=(
                ("mode", "controlled"),
            ),
            isolation_label="isolated",
            seed=42,
        )

        self.engine.register_experiment(
            experiment
        )

        values = (
            0.70,
            0.72,
            0.71,
            0.73,
        )

        for index, value in enumerate(
            values,
            start=1,
        ):

            self.engine.record_trial(
                BenchmarkTrial(
                    trial_id=f"trial-{index}",
                    experiment_id=(
                        "experiment-1"
                    ),
                    repetition=index,
                    metric_value=value,
                    status=(
                        TrialStatus.COMPLETED
                    ),
                    seed=42 + index,
                    execution_reference=(
                        f"execution-{index}"
                    ),
                )
            )

        summary = (
            self.engine.summarize_experiment(
                "experiment-1"
            )
        )

        self.assertEqual(
            summary.count,
            4,
        )

        self.assertAlmostEqual(
            summary.average,
            0.715,
        )

        self.assertGreaterEqual(
            summary.confidence_interval_high,
            summary.average,
        )

    # ========================================================================
    # Comparison
    # ========================================================================

    def test_baseline_comparison(self):

        baseline = BenchmarkBaseline(
            baseline_id="baseline-2",
            benchmark_id="benchmark-1",
            name="Baseline",
            values=(
                0.60,
                0.60,
                0.60,
                0.60,
            ),
            source_reference="baseline",
        )

        self.engine.register_baseline(
            baseline
        )

        experiment = BenchmarkExperiment(
            experiment_id="experiment-2",
            benchmark_id="benchmark-1",
            configuration=(),
            isolation_label="isolated",
            seed=10,
        )

        self.engine.register_experiment(
            experiment
        )

        for index, value in enumerate(
            (0.70, 0.71, 0.72, 0.73),
            start=1,
        ):

            self.engine.record_trial(
                BenchmarkTrial(
                    trial_id=f"cmp-{index}",
                    experiment_id=(
                        "experiment-2"
                    ),
                    repetition=index,
                    metric_value=value,
                    status=(
                        TrialStatus.COMPLETED
                    ),
                    seed=10,
                    execution_reference=(
                        f"cmp-exec-{index}"
                    ),
                )
            )

        comparison = (
            self.engine.compare_with_baseline(
                "experiment-2",
                "baseline-2",
            )
        )

        self.assertEqual(
            comparison.status,
            ComparisonStatus.BETTER,
        )

        self.assertGreater(
            comparison.absolute_delta,
            0.0,
        )

    # ========================================================================
    # Reproducibility
    # ========================================================================

    def test_reproducibility(self):

        experiment = BenchmarkExperiment(
            experiment_id="experiment-repro",
            benchmark_id="benchmark-1",
            configuration=(),
            isolation_label="isolated",
            seed=123,
        )

        self.engine.register_experiment(
            experiment
        )

        first = (
            ScientificBenchmarkingEngine
            .deterministic_trial_values(
                123,
                10,
            )
        )

        second = (
            ScientificBenchmarkingEngine
            .deterministic_trial_values(
                123,
                10,
            )
        )

        record = (
            self.engine.record_reproducibility(
                "experiment-repro",
                first,
                second,
                123,
            )
        )

        self.assertTrue(
            record.identical
        )

    # ========================================================================
    # Reproducibility failure
    # ========================================================================

    def test_reproducibility_failure(self):

        experiment = BenchmarkExperiment(
            experiment_id="experiment-repro-fail",
            benchmark_id="benchmark-1",
            configuration=(),
            isolation_label="isolated",
            seed=1,
        )

        self.engine.register_experiment(
            experiment
        )

        record = (
            self.engine.record_reproducibility(
                "experiment-repro-fail",
                (0.1, 0.2),
                (0.1, 0.3),
                1,
            )
        )

        self.assertFalse(
            record.identical
        )

    # ========================================================================
    # Failure analysis
    # ========================================================================

    def test_failure_analysis(self):

        experiment = BenchmarkExperiment(
            experiment_id="experiment-failure",
            benchmark_id="benchmark-1",
            configuration=(),
            isolation_label="isolated",
            seed=5,
        )

        self.engine.register_experiment(
            experiment
        )

        trial = BenchmarkTrial(
            trial_id="failure-trial",
            experiment_id="experiment-failure",
            repetition=1,
            metric_value=0.0,
            status=TrialStatus.FAILED,
            seed=5,
            execution_reference="failed-execution",
            failure_category=(
                FailureCategory.DETECTION
            ),
            failure_reason=(
                "expected detection "
                "was not observed"
            ),
        )

        self.engine.record_trial(
            trial
        )

        failure = FailureAnalysis(
            failure_id="failure-1",
            benchmark_id="benchmark-1",
            experiment_id="experiment-failure",
            trial_id="failure-trial",
            category=FailureCategory.DETECTION,
            reason=(
                "defensive detection failure"
            ),
            reproducible=False,
        )

        self.engine.record_failure(
            failure
        )

        self.assertEqual(
            len(
                self.engine.failures_for_benchmark(
                    "benchmark-1"
                )
            ),
            1,
        )

    # ========================================================================
    # Run
    # ========================================================================

    def test_benchmark_run(self):

        experiment = BenchmarkExperiment(
            experiment_id="experiment-run",
            benchmark_id="benchmark-1",
            configuration=(),
            isolation_label="isolated",
            seed=9,
        )

        self.engine.register_experiment(
            experiment
        )

        for index, value in enumerate(
            (0.80, 0.81),
            start=1,
        ):

            self.engine.record_trial(
                BenchmarkTrial(
                    trial_id=f"run-{index}",
                    experiment_id=(
                        "experiment-run"
                    ),
                    repetition=index,
                    metric_value=value,
                    status=(
                        TrialStatus.COMPLETED
                    ),
                    seed=9,
                    execution_reference=(
                        f"run-exec-{index}"
                    ),
                )
            )

        run = self.engine.create_run(
            "benchmark-1",
            ["experiment-run"],
        )

        completed = (
            self.engine.complete_run(
                run.run_id
            )
        )

        self.assertEqual(
            completed.status,
            BenchmarkStatus.COMPLETED,
        )

    # ========================================================================
    # Scope/reference validation
    # ========================================================================

    def test_invalid_baseline_reference(self):

        with self.assertRaises(KeyError):

            self.engine.register_baseline(
                BenchmarkBaseline(
                    baseline_id="bad-baseline",
                    benchmark_id="missing",
                    name="Bad",
                    values=(1.0,),
                    source_reference="bad",
                )
            )

    # ========================================================================
    # Global validation
    # ========================================================================

    def test_global_validation(self):

        self.assertEqual(
            self.engine.validate(),
            [],
        )


# ============================================================================
# TEST ENTRYPOINT
# ============================================================================

def run_phase24_tests() -> None:

    suite = (
        unittest.defaultTestLoader
        .loadTestsFromTestCase(
            Phase24Tests
        )
    )

    result = unittest.TextTestRunner(
        verbosity=2
    ).run(suite)

    if not result.wasSuccessful():

        raise AssertionError(
            "Phase 24 tests failed"
        )


if __name__ == "__main__":
    run_phase24_tests()
