# ============================================================================
# ENTERPRISE HARDENING ENGINE
# ============================================================================

class EnterpriseHardeningEngine:

    """
    Phase 25 enterprise hardening coordinator.

    The engine validates and records defensive enterprise controls.
    It does not automatically deploy them into production.
    """

    FINGERPRINT_LENGTH = 64

    def __init__(self) -> None:

        self._tenants: Dict[
            str,
            TenantBoundary,
        ] = {}

        self._principals: Dict[
            str,
            SecurityPrincipal,
        ] = {}

        self._access_policies: Dict[
            str,
            AccessPolicy,
        ] = {}

        self._secrets: Dict[
            str,
            SecretMetadata,
        ] = {}

        self._api_keys: Dict[
            str,
            APIKeyRecord,
        ] = {}

        self._audit: Dict[
            str,
            AuditRecord,
        ] = {}

        self._artifact_integrity: Dict[
            str,
            ArtifactIntegrityRecord,
        ] = {}

        self._resource_policies: Dict[
            str,
            ResourceProtectionPolicy,
        ] = {}

        self._containment_policies: Dict[
            str,
            FailureContainmentPolicy,
        ] = {}

        self._backups: Dict[
            str,
            BackupRecord,
        ] = {}

        self._deployment_policies: Dict[
            str,
            DeploymentSecurityPolicy,
        ] = {}

        self._findings: Dict[
            str,
            HardeningFinding,
        ] = {}

        self._lock = RLock()

    # ========================================================================
    # TENANT ISOLATION
    # ========================================================================

    def register_tenant(
        self,
        tenant: TenantBoundary,
    ) -> None:

        with self._lock:

            if tenant.tenant_id in self._tenants:
                raise ValueError(
                    "duplicate tenant"
                )

            self._tenants[
                tenant.tenant_id
            ] = tenant

    def verify_tenant_scope(
        self,
        tenant_id: str,
        resource_scope: str,
    ) -> bool:

        with self._lock:

            tenant = self._tenants.get(
                tenant_id
            )

            if tenant is None:
                return False

            return resource_scope in (
                tenant.allowed_component_scopes
            )

    # ========================================================================
    # PRINCIPALS
    # ========================================================================

    def register_principal(
        self,
        principal: SecurityPrincipal,
    ) -> None:

        with self._lock:

            if principal.tenant_id not in (
                self._tenants
            ):
                raise KeyError(
                    "tenant not found"
                )

            if principal.principal_id in (
                self._principals
            ):
                raise ValueError(
                    "duplicate principal"
                )

            self._principals[
                principal.principal_id
            ] = principal

    # ========================================================================
    # RBAC / ABAC
    # ========================================================================

    def register_access_policy(
        self,
        policy: AccessPolicy,
    ) -> None:

        with self._lock:

            if policy.tenant_id not in (
                self._tenants
            ):
                raise KeyError(
                    "tenant not found"
                )

            if policy.policy_id in (
                self._access_policies
            ):
                raise ValueError(
                    "duplicate access policy"
                )

            self._access_policies[
                policy.policy_id
            ] = policy

    @staticmethod
    def _attributes_match(
        principal: SecurityPrincipal,
        required: Tuple[
            Tuple[str, str],
            ...
        ],
    ) -> bool:

        attributes = dict(
            principal.attributes
        )

        return all(
            attributes.get(key) == value
            for key, value in required
        )

    def authorize(
        self,
        principal_id: str,
        resource_scope: str,
    ) -> AccessEffect:

        with self._lock:

            principal = self._principals.get(
                principal_id
            )

            if principal is None:
                return AccessEffect.DENY

            if not principal.active:
                return AccessEffect.DENY

            if not self.verify_tenant_scope(
                principal.tenant_id,
                resource_scope,
            ):
                return AccessEffect.DENY

            matching = [
                policy
                for policy
                in self._access_policies.values()
                if (
                    policy.tenant_id
                    == principal.tenant_id
                    and policy.resource_pattern
                    == resource_scope
                    and (
                        not policy.allowed_roles
                        or bool(
                            principal.roles
                            & policy.allowed_roles
                        )
                    )
                    and self._attributes_match(
                        principal,
                        policy.required_attributes,
                    )
                )
            ]

            if not matching:
                return AccessEffect.DENY

            matching.sort(
                key=lambda item: item.priority,
                reverse=True,
            )

            return matching[0].effect

    # ========================================================================
    # SECRETS
    # ========================================================================

    @staticmethod
    def fingerprint_secret(
        secret_value: str,
    ) -> str:

        if not secret_value:
            raise ValueError(
                "secret value required"
            )

        return hashlib.sha256(
            secret_value.encode("utf-8")
        ).hexdigest()

    def register_secret_metadata(
        self,
        metadata: SecretMetadata,
    ) -> None:

        with self._lock:

            if metadata.tenant_id not in (
                self._tenants
            ):
                raise KeyError(
                    "tenant not found"
                )

            if metadata.secret_id in (
                self._secrets
            ):
                raise ValueError(
                    "duplicate secret"
                )

            self._secrets[
                metadata.secret_id
            ] = metadata

    def secret_requires_rotation(
        self,
        secret_id: str,
        now: Optional[datetime] = None,
    ) -> bool:

        metadata = self._secrets.get(
            secret_id
        )

        if metadata is None:
            raise KeyError(
                "secret not found"
            )

        moment = now or utc_now()
        ensure_aware(moment)

        return (
            metadata.state
            in {
                SecretState.ROTATION_REQUIRED,
                SecretState.REVOKED,
            }
            or moment >= metadata.expires_at
        )

    # ========================================================================
    # API SECURITY
    # ========================================================================

    @staticmethod
    def fingerprint_api_key(
        raw_key: str,
    ) -> str:

        if len(raw_key) < 32:
            raise ValueError(
                "API key is too short"
            )

        return hashlib.sha256(
            raw_key.encode("utf-8")
        ).hexdigest()

    def register_api_key(
        self,
        record: APIKeyRecord,
    ) -> None:

        with self._lock:

            if record.tenant_id not in (
                self._tenants
            ):
                raise KeyError(
                    "tenant not found"
                )

            if record.key_id in (
                self._api_keys
            ):
                raise ValueError(
                    "duplicate API key"
                )

            self._api_keys[
                record.key_id
            ] = record

    def validate_api_key(
        self,
        key_id: str,
        presented_key: str,
        required_scope: Optional[str] = None,
        now: Optional[datetime] = None,
    ) -> bool:

        record = self._api_keys.get(
            key_id
        )

        if record is None:
            return False

        if record.state != (
            APIKeyState.ACTIVE
        ):
            return False

        moment = now or utc_now()
        ensure_aware(moment)

        if moment >= record.expires_at:
            return False

        presented_fingerprint = (
            self.fingerprint_api_key(
                presented_key
            )
        )

        if not hmac.compare_digest(
            presented_fingerprint,
            record.key_fingerprint,
        ):
            return False

        if (
            required_scope is not None
            and required_scope
            not in record.scopes
        ):
            return False

        return True

    # ========================================================================
    # AUDIT
    # ========================================================================

    def append_audit(
        self,
        tenant_id: str,
        actor_id: str,
        action: str,
        resource: str,
        outcome: str,
    ) -> AuditRecord:

        with self._lock:

            if tenant_id not in self._tenants:
                raise KeyError(
                    "tenant not found"
                )

            previous_hash = (
                "GENESIS"
            )

            if self._audit:
                previous_hash = list(
                    self._audit.values()
                )[-1].record_hash

            timestamp = utc_now()

            record_hash = stable_hash(
                tenant_id,
                actor_id,
                action,
                resource,
                outcome,
                timestamp.isoformat(),
                previous_hash,
            )

            record = AuditRecord(
                audit_id=stable_hash(
                    "audit",
                    record_hash,
                ),
                tenant_id=tenant_id,
                actor_id=actor_id,
                action=action,
                resource=resource,
                outcome=outcome,
                timestamp=timestamp,
                previous_hash=previous_hash,
                record_hash=record_hash,
            )

            self._audit[
                record.audit_id
            ] = record

            return record

    def verify_audit_integrity(self) -> AuditIntegrityStatus:

        with self._lock:

            previous = "GENESIS"

            for record in self._audit.values():

                expected = stable_hash(
                    record.tenant_id,
                    record.actor_id,
                    record.action,
                    record.resource,
                    record.outcome,
                    record.timestamp.isoformat(),
                    previous,
                )

                if not hmac.compare_digest(
                    expected,
                    record.record_hash,
                ):
                    return (
                        AuditIntegrityStatus.INVALID
                    )

                if record.previous_hash != previous:
                    return (
                        AuditIntegrityStatus.INVALID
                    )

                previous = record.record_hash

            return AuditIntegrityStatus.VALID

    # ========================================================================
    # SUPPLY CHAIN
    # ========================================================================

    def register_artifact_integrity(
        self,
        record: ArtifactIntegrityRecord,
    ) -> None:

        with self._lock:

            if record.artifact_id in (
                self._artifact_integrity
            ):
                raise ValueError(
                    "duplicate artifact"
                )

            self._artifact_integrity[
                record.artifact_id
            ] = record

    @staticmethod
    def verify_artifact_digest(
        expected_digest: str,
        observed_digest: str,
    ) -> SupplyChainStatus:

        if not expected_digest or not observed_digest:
            return SupplyChainStatus.UNKNOWN

        if hmac.compare_digest(
            expected_digest,
            observed_digest,
        ):
            return SupplyChainStatus.VERIFIED

        return SupplyChainStatus.MISMATCH

    # ========================================================================
    # RESOURCE PROTECTION
    # ========================================================================

    def register_resource_policy(
        self,
        policy: ResourceProtectionPolicy,
    ) -> None:

        with self._lock:

            if policy.tenant_id not in (
                self._tenants
            ):
                raise KeyError(
                    "tenant not found"
                )

            if policy.policy_id in (
                self._resource_policies
            ):
                raise ValueError(
                    "duplicate resource policy"
                )

            self._resource_policies[
                policy.policy_id
            ] = policy

    # ========================================================================
    # FAILURE CONTAINMENT
    # ========================================================================

    def register_containment_policy(
        self,
        policy: FailureContainmentPolicy,
    ) -> None:

        with self._lock:

            if policy.tenant_id not in (
                self._tenants
            ):
                raise KeyError(
                    "tenant not found"
                )

            if policy.policy_id in (
                self._containment_policies
            ):
                raise ValueError(
                    "duplicate containment policy"
                )

            self._containment_policies[
                policy.policy_id
            ] = policy

    def containment_state(
        self,
        policy_id: str,
        *,
        integrity_failure: bool = False,
        authority_failure: bool = False,
    ) -> ContainmentState:

        policy = self._containment_policies.get(
            policy_id
        )

        if policy is None:
            raise KeyError(
                "containment policy not found"
            )

        if (
            integrity_failure
            and policy.isolate_on_integrity_failure
        ):
            return (
                ContainmentState.CONTAINED
            )

        if (
            authority_failure
            and policy.isolate_on_authority_failure
        ):
            return (
                ContainmentState.CONTAINED
            )

        return ContainmentState.NORMAL

    # ========================================================================
    # BACKUP / RECOVERY PROTECTION
    # ========================================================================

    def register_backup(
        self,
        backup: BackupRecord,
    ) -> None:

        with self._lock:

            if backup.tenant_id not in (
                self._tenants
            ):
                raise KeyError(
                    "tenant not found"
                )

            if backup.backup_id in (
                self._backups
            ):
                raise ValueError(
                    "duplicate backup"
                )

            self._backups[
                backup.backup_id
            ] = backup

    def validate_backup(
        self,
        backup_id: str,
        now: Optional[datetime] = None,
    ) -> bool:

        backup = self._backups.get(
            backup_id
        )

        if backup is None:
            return False

        moment = now or utc_now()
        ensure_aware(moment)

        return (
            backup.status
            == BackupStatus.AVAILABLE
            and backup.encrypted
            and backup.integrity_verified
            and moment < backup.expires_at
        )

    # ========================================================================
    # DEPLOYMENT SECURITY
    # ========================================================================

    def register_deployment_policy(
        self,
        policy: DeploymentSecurityPolicy,
    ) -> None:

        with self._lock:

            if policy.tenant_id not in (
                self._tenants
            ):
                raise KeyError(
                    "tenant not found"
                )

            if policy.policy_id in (
                self._deployment_policies
            ):
                raise ValueError(
                    "duplicate deployment policy"
                )

            self._deployment_policies[
                policy.policy_id
            ] = policy

    def evaluate_deployment(
        self,
        policy_id: str,
    ) -> DeploymentStatus:

        policy = self._deployment_policies.get(
            policy_id
        )

        if policy is None:
            return DeploymentStatus.UNKNOWN

        tenant_id = policy.tenant_id

        if (
            policy.require_tenant_isolation
            and tenant_id not in self._tenants
        ):
            return DeploymentStatus.BLOCKED

        if (
            policy.require_access_control
            and not any(
                p.tenant_id == tenant_id
                for p in self._access_policies.values()
            )
        ):
            return DeploymentStatus.BLOCKED

        if policy.require_audit_enabled:

            if self.verify_audit_integrity() != (
                AuditIntegrityStatus.VALID
            ):
                return DeploymentStatus.BLOCKED

        if policy.require_integrity_verified:

            tenant_artifacts = [
                record
                for record
                in self._artifact_integrity.values()
            ]

            if not tenant_artifacts:
                return DeploymentStatus.BLOCKED

            if any(
                record.status
                != SupplyChainStatus.VERIFIED
                for record in tenant_artifacts
            ):
                return DeploymentStatus.BLOCKED

        if policy.require_fail_closed:

            containment_exists = any(
                item.tenant_id == tenant_id
                and item.fail_closed
                for item
                in self._containment_policies.values()
            )

            if not containment_exists:
                return DeploymentStatus.BLOCKED

        if policy.require_encrypted_backups:

            valid_backup = any(
                backup.tenant_id == tenant_id
                and self.validate_backup(
                    backup.backup_id
                )
                for backup
                in self._backups.values()
            )

            if not valid_backup:
                return DeploymentStatus.BLOCKED

        return DeploymentStatus.APPROVED

    # ========================================================================
    # FINDINGS
    # ========================================================================

    def add_finding(
        self,
        finding: HardeningFinding,
    ) -> None:

        with self._lock:

            if finding.tenant_id not in (
                self._tenants
            ):
                raise KeyError(
                    "tenant not found"
                )

            if finding.finding_id in (
                self._findings
            ):
                raise ValueError(
                    "duplicate finding"
                )

            self._findings[
                finding.finding_id
            ] = finding

    def open_findings(
        self,
        tenant_id: str,
    ) -> Tuple[
        HardeningFinding,
        ...
    ]:

        return tuple(
            finding
            for finding
            in self._findings.values()
            if (
                finding.tenant_id == tenant_id
                and finding.status
                == FindingStatus.OPEN
            )
        )

    # ========================================================================
    # GLOBAL VALIDATION
    # ========================================================================

    def validate(self) -> List[str]:

        errors: List[str] = []

        with self._lock:

            # Tenant validation
            for tenant_id, tenant in (
                self._tenants.items()
            ):

                if tenant_id != tenant.tenant_id:
                    errors.append(
                        "tenant key mismatch"
                    )

                if not tenant.isolation_namespace:
                    errors.append(
                        f"tenant {tenant_id} "
                        "has empty isolation namespace"
                    )

            # Principal validation
            for principal_id, principal in (
                self._principals.items()
            ):

                if principal_id != principal.principal_id:
                    errors.append(
                        "principal key mismatch"
                    )

                if principal.tenant_id not in (
                    self._tenants
                ):
                    errors.append(
                        f"principal {principal_id} "
                        "references unknown tenant"
                    )

            # Access policy validation
            for policy_id, policy in (
                self._access_policies.items()
            ):

                if policy_id != policy.policy_id:
                    errors.append(
                        "access policy key mismatch"
                    )

                if policy.tenant_id not in (
                    self._tenants
                ):
                    errors.append(
                        f"access policy {policy_id} "
                        "references unknown tenant"
                    )

            # Secret metadata validation
            for secret_id, secret in (
                self._secrets.items()
            ):

                if secret_id != secret.secret_id:
                    errors.append(
                        "secret key mismatch"
                    )

                if secret.tenant_id not in (
                    self._tenants
                ):
                    errors.append(
                        f"secret {secret_id} "
                        "references unknown tenant"
                    )

            # API key validation
            for key_id, record in (
                self._api_keys.items()
            ):

                if key_id != record.key_id:
                    errors.append(
                        "API key key mismatch"
                    )

                if record.tenant_id not in (
                    self._tenants
                ):
                    errors.append(
                        f"API key {key_id} "
                        "references unknown tenant"
                    )

                if len(record.key_fingerprint) != (
                    self.FINGERPRINT_LENGTH
                ):
                    errors.append(
                        f"API key {key_id} "
                        "has invalid fingerprint length"
                    )

            # Artifact validation
            for artifact_id, artifact in (
                self._artifact_integrity.items()
            ):

                if artifact_id != artifact.artifact_id:
                    errors.append(
                        "artifact key mismatch"
                    )

                if (
                    artifact.status
                    == SupplyChainStatus.VERIFIED
                    and not hmac.compare_digest(
                        artifact.expected_digest,
                        artifact.observed_digest,
                    )
                ):
                    errors.append(
                        f"artifact {artifact_id} "
                        "marked VERIFIED despite digest mismatch"
                    )

            # Backup validation
            for backup_id, backup in (
                self._backups.items()
            ):

                if backup_id != backup.backup_id:
                    errors.append(
                        "backup key mismatch"
                    )

                if backup.tenant_id not in (
                    self._tenants
                ):
                    errors.append(
                        f"backup {backup_id} "
                        "references unknown tenant"
                    )

                if (
                    backup.status
                    == BackupStatus.AVAILABLE
                    and (
                        not backup.encrypted
                        or not backup.integrity_verified
                    )
                ):
                    errors.append(
                        f"backup {backup_id} "
                        "marked AVAILABLE without required protection"
                    )

            # Audit chain
            if self._audit:

                if self.verify_audit_integrity() != (
                    AuditIntegrityStatus.VALID
                ):
                    errors.append(
                        "audit chain integrity failure"
                    )

            # Deployment policies
            for policy_id, policy in (
                self._deployment_policies.items()
            ):

                if policy_id != policy.policy_id:
                    errors.append(
                        "deployment policy key mismatch"
                    )

                if policy.tenant_id not in (
                    self._tenants
                ):
                    errors.append(
                        f"deployment policy {policy_id} "
                        "references unknown tenant"
                    )

        return errors


# ============================================================================
# TESTS
# ============================================================================

class Phase25Tests(unittest.TestCase):

    def setUp(self):

        self.engine = (
            EnterpriseHardeningEngine()
        )

        self.tenant = TenantBoundary(
            tenant_id="tenant-a",
            isolation_namespace="tenant-a-isolated",
            allowed_component_scopes=frozenset(
                {
                    "state",
                    "agent",
                    "memory",
                }
            ),
        )

        self.engine.register_tenant(
            self.tenant
        )

    # ========================================================================
    # Tenant isolation
    # ========================================================================

    def test_tenant_isolation(self):

        self.assertTrue(
            self.engine.verify_tenant_scope(
                "tenant-a",
                "state",
            )
        )

        self.assertFalse(
            self.engine.verify_tenant_scope(
                "tenant-a",
                "other-tenant-resource",
            )
        )

    # ========================================================================
    # RBAC
    # ========================================================================

    def test_rbac_authorization(self):

        principal = SecurityPrincipal(
            principal_id="operator-1",
            tenant_id="tenant-a",
            roles=frozenset({"security-admin"}),
            attributes=(
                ("environment", "controlled"),
            ),
            authentication_method=(
                AuthenticationMethod.OIDC
            ),
        )

        self.engine.register_principal(
            principal
        )

        policy = AccessPolicy(
            policy_id="policy-1",
            tenant_id="tenant-a",
            resource_pattern="state",
            allowed_roles=frozenset(
                {"security-admin"}
            ),
            required_attributes=(
                ("environment", "controlled"),
            ),
            effect=AccessEffect.ALLOW,
            priority=10,
        )

        self.engine.register_access_policy(
            policy
        )

        self.assertEqual(
            self.engine.authorize(
                "operator-1",
                "state",
            ),
            AccessEffect.ALLOW,
        )

    # ========================================================================
    # Cross-tenant denial
    # ========================================================================

    def test_cross_tenant_denial(self):

        principal = SecurityPrincipal(
            principal_id="operator-2",
            tenant_id="tenant-a",
            roles=frozenset({"admin"}),
            attributes=(),
            authentication_method=(
                AuthenticationMethod.SERVICE_IDENTITY
            ),
        )

        self.engine.register_principal(
            principal
        )

        self.assertEqual(
            self.engine.authorize(
                "operator-2",
                "tenant-b-secret",
            ),
            AccessEffect.DENY,
        )

    # ========================================================================
    # Secret fingerprint
    # ========================================================================

    def test_secret_fingerprint(self):

        fingerprint = (
            self.engine.fingerprint_secret(
                "controlled-secret-value"
            )
        )

        self.assertEqual(
            len(fingerprint),
            64,
        )

        metadata = SecretMetadata(
            secret_id="secret-1",
            tenant_id="tenant-a",
            purpose="connector credential",
            state=SecretState.ACTIVE,
            created_at=utc_now(),
            expires_at=(
                utc_now()
                + timedelta(days=30)
            ),
            version=1,
            fingerprint=fingerprint,
        )

        self.engine.register_secret_metadata(
            metadata
        )

        self.assertFalse(
            self.engine.secret_requires_rotation(
                "secret-1"
            )
        )

    # ========================================================================
    # API key
    # ========================================================================

    def test_api_key_validation(self):

        raw_key = (
            "A" * 40
        )

        fingerprint = (
            self.engine.fingerprint_api_key(
                raw_key
            )
        )

        record = APIKeyRecord(
            key_id="api-1",
            tenant_id="tenant-a",
            key_fingerprint=fingerprint,
            state=APIKeyState.ACTIVE,
            scopes=frozenset(
                {"read", "security"}
            ),
            created_at=utc_now(),
            expires_at=(
                utc_now()
                + timedelta(days=1)
            ),
        )

        self.engine.register_api_key(
            record
        )

        self.assertTrue(
            self.engine.validate_api_key(
                "api-1",
                raw_key,
                "security",
            )
        )

        self.assertFalse(
            self.engine.validate_api_key(
                "api-1",
                "wrong-key-" + ("B" * 32),
                "security",
            )
        )

    # ========================================================================
    # Audit chain
    # ========================================================================

    def test_audit_integrity(self):

        self.engine.append_audit(
            "tenant-a",
            "operator",
            "READ",
            "state",
            "ALLOW",
        )

        self.engine.append_audit(
            "tenant-a",
            "operator",
            "VERIFY",
            "state",
            "SUCCESS",
        )

        self.assertEqual(
            self.engine.verify_audit_integrity(),
            AuditIntegrityStatus.VALID,
        )

    # ========================================================================
    # Supply chain
    # ========================================================================

    def test_supply_chain_digest(self):

        digest = hashlib.sha256(
            b"trusted-artifact"
        ).hexdigest()

        self.assertEqual(
            self.engine.verify_artifact_digest(
                digest,
                digest,
            ),
            SupplyChainStatus.VERIFIED,
        )

        self.assertEqual(
            self.engine.verify_artifact_digest(
                digest,
                hashlib.sha256(
                    b"modified-artifact"
                ).hexdigest(),
            ),
            SupplyChainStatus.MISMATCH,
        )

    # ========================================================================
    # Failure containment
    # ========================================================================

    def test_failure_containment(self):

        policy = FailureContainmentPolicy(
            policy_id="containment-1",
            tenant_id="tenant-a",
            component_scope="agent",
            fail_closed=True,
            isolate_on_integrity_failure=True,
            isolate_on_authority_failure=True,
        )

        self.engine.register_containment_policy(
            policy
        )

        self.assertEqual(
            self.engine.containment_state(
                "containment-1",
                integrity_failure=True,
            ),
            ContainmentState.CONTAINED,
        )

    # ========================================================================
    # Backup
    # ========================================================================

    def test_backup_validation(self):

        backup = BackupRecord(
            backup_id="backup-1",
            tenant_id="tenant-a",
            scope="tenant-a-state",
            content_digest="digest",
            created_at=utc_now(),
            expires_at=(
                utc_now()
                + timedelta(days=7)
            ),
            status=BackupStatus.AVAILABLE,
            encrypted=True,
            integrity_verified=True,
        )

        self.engine.register_backup(
            backup
        )

        self.assertTrue(
            self.engine.validate_backup(
                "backup-1"
            )
        )

    # ========================================================================
    # Deployment policy
    # ========================================================================

    def test_deployment_blocked_without_controls(self):

        policy = DeploymentSecurityPolicy(
            policy_id="deploy-1",
            tenant_id="tenant-a",
        )

        self.engine.register_deployment_policy(
            policy
        )

        self.assertEqual(
            self.engine.evaluate_deployment(
                "deploy-1"
            ),
            DeploymentStatus.BLOCKED,
        )

    # ========================================================================
    # Deployment approved with required controls
    # ========================================================================

    def test_deployment_approved_with_controls(self):

        # Access control
        self.engine.register_access_policy(
            AccessPolicy(
                policy_id="access-1",
                tenant_id="tenant-a",
                resource_pattern="state",
                allowed_roles=frozenset(
                    {"admin"}
                ),
                required_attributes=(),
                effect=AccessEffect.ALLOW,
            )
        )

        # Audit
        self.engine.append_audit(
            "tenant-a",
            "system",
            "HARDENING_CHECK",
            "enterprise",
            "SUCCESS",
        )

        # Supply-chain integrity
        digest = hashlib.sha256(
            b"trusted"
        ).hexdigest()

        self.engine.register_artifact_integrity(
            ArtifactIntegrityRecord(
                artifact_id="artifact-1",
                component_name="core",
                expected_digest=digest,
                observed_digest=digest,
                status=SupplyChainStatus.VERIFIED,
                source_reference="trusted-source",
            )
        )

        # Fail-closed containment
        self.engine.register_containment_policy(
            FailureContainmentPolicy(
                policy_id="containment-2",
                tenant_id="tenant-a",
                component_scope="core",
                fail_closed=True,
                isolate_on_integrity_failure=True,
                isolate_on_authority_failure=True,
            )
        )

        # Protected backup
        self.engine.register_backup(
            BackupRecord(
                backup_id="backup-2",
                tenant_id="tenant-a",
                scope="tenant-a",
                content_digest="backup-digest",
                created_at=utc_now(),
                expires_at=(
                    utc_now()
                    + timedelta(days=7)
                ),
                status=BackupStatus.AVAILABLE,
                encrypted=True,
                integrity_verified=True,
            )
        )

        # Deployment policy
        self.engine.register_deployment_policy(
            DeploymentSecurityPolicy(
                policy_id="deploy-2",
                tenant_id="tenant-a",
            )
        )

        self.assertEqual(
            self.engine.evaluate_deployment(
                "deploy-2"
            ),
            DeploymentStatus.APPROVED,
        )

    # ========================================================================
    # Global validation
    # ========================================================================

    def test_global_validation(self):

        self.assertEqual(
            self.engine.validate(),
            [],
        )


# ============================================================================
# TEST ENTRYPOINT
# ============================================================================

def run_phase25_tests() -> None:

    suite = (
        unittest.defaultTestLoader
        .loadTestsFromTestCase(
            Phase25Tests
        )
    )

    result = unittest.TextTestRunner(
        verbosity=2
    ).run(suite)

    if not result.wasSuccessful():
        raise AssertionError(
            "Phase 25 tests failed"
        )


if __name__ == "__main__":
    run_phase25_tests()
