# ============================================================================

class EvidenceType(str, Enum):
    ARCHITECTURE = "ARCHITECTURE"
    IMPLEMENTATION = "IMPLEMENTATION"
    TEST = "TEST"
    BENCHMARK = "BENCHMARK"
    EXPERIMENT = "EXPERIMENT"
    VALIDATION = "VALIDATION"
    PRIOR_ART = "PRIOR_ART"
    DOCUMENTATION = "DOCUMENTATION"


class EvidenceStatus(str, Enum):
    VERIFIED = "VERIFIED"
    UNVERIFIED = "UNVERIFIED"
    CONTRADICTED = "CONTRADICTED"
    INSUFFICIENT = "INSUFFICIENT"


class NoveltyAssessment(str, Enum):
    DISTINCT = "DISTINCT"
    PARTIALLY_DISTINCT = "PARTIALLY_DISTINCT"
    OVERLAP = "OVERLAP"
    UNKNOWN = "UNKNOWN"


class DifferentiationStrength(str, Enum):
    STRONG = "STRONG"
    MODERATE = "MODERATE"
    WEAK = "WEAK"
    UNKNOWN = "UNKNOWN"


class ContributionType(str, Enum):
    ARCHITECTURAL = "ARCHITECTURAL"
    ALGORITHMIC = "ALGORITHMIC"
    CONTROL = "CONTROL"
    VERIFICATION = "VERIFICATION"
    RESILIENCE = "RESILIENCE"
    MEMORY = "MEMORY"
    AUTONOMY = "AUTONOMY"
    SECURITY = "SECURITY"
    INTEGRATION = "INTEGRATION"


class UncertaintyType(str, Enum):
    PRIOR_ART_GAP = "PRIOR_ART_GAP"
    IMPLEMENTATION_GAP = "IMPLEMENTATION_GAP"
    EVIDENCE_GAP = "EVIDENCE_GAP"
    EXPERIMENT_GAP = "EXPERIMENT_GAP"
    CLAIM_SCOPE = "CLAIM_SCOPE"
    TECHNICAL_LIMITATION = "TECHNICAL_LIMITATION"


class CandidateStatus(str, Enum):
    REVIEW = "REVIEW"
    NOT_READY = "NOT_READY"
    REJECTED = "REJECTED"


class FinalValidationStatus(str, Enum):
    PASS = "PASS"
    FAIL = "FAIL"
    INCONCLUSIVE = "INCONCLUSIVE"


class LimitationSeverity(str, Enum):
    LOW = "LOW"
    MEDIUM = "MEDIUM"
    HIGH = "HIGH"
    CRITICAL = "CRITICAL"


